// app/api/health/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { connectToDatabase } from '@/lib/db/mongo'; // Use path alias or adjust path as needed

// Define types for health check response
type HealthStatus = 'healthy' | 'warning' | 'error';

interface ServiceHealth {
  status: HealthStatus;
  details?: Record<string, any>;
}

interface HealthCheckResponse {
  status: HealthStatus;
  environment: string;
  version: string;
  timestamp: string;
  services: {
    web: ServiceHealth;
    mongodb: ServiceHealth;
    chromadb: ServiceHealth;
  };
}

interface ErrorResponse {
  status: 'error';
  environment: string;
  version: string;
  timestamp: string;
  error: string;
}

/**
 * Check MongoDB connection health
 */
async function checkMongoDBHealth(): Promise<ServiceHealth> {
  try {
    const { db } = await connectToDatabase();

    // Ping MongoDB to verify connection
    await db.command({ ping: 1 });

    // Get some basic stats
    const serverStatus = await db.command({ serverStatus: 1 });

    return {
      status: 'healthy',
      details: {
        version: serverStatus.version,
        uptime: serverStatus.uptime,
        connections: serverStatus.connections.current,
      },
    };
  } catch (error) {
    console.error('MongoDB health check failed:', error);
    return {
      status: 'error',
      details: {
        message: (error as Error).message,
      },
    };
  }
}

/**
 * Check ChromaDB connection health
 */
async function checkChromaDBHealth(): Promise<ServiceHealth> {
  try {
    // Try to connect to ChromaDB heartbeat endpoint
    const response = await fetch('http://localhost:8000/api/v1/heartbeat', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
      // Add timeout to avoid hanging
      signal: AbortSignal.timeout(2000), // 2-second timeout
    });

    if (!response.ok) {
      throw new Error(`ChromaDB returned status: ${response.status}`);
    }

    // Get collections to add detail
    const collectionsResponse = await fetch(
      'http://localhost:8000/api/v1/collections',
      {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      },
    );

    let collections: any[] = [];
    if (collectionsResponse.ok) {
      collections = await collectionsResponse.json();
    }

    return {
      status: 'healthy',
      details: {
        collectionCount: Array.isArray(collections) ? collections.length : 0,
      },
    };
  } catch (error) {
    console.error('ChromaDB health check failed:', error);
    return {
      status: 'error',
      details: {
        message: (error as Error).message,
      },
    };
  }
}

/**
 * Health check API endpoint
 */
export async function GET(req: NextRequest): Promise<NextResponse> {
  const environment = process.env.NODE_ENV || 'development';
  const version = process.env.APP_VERSION || '1.0.0';
  const timestamp = new Date().toISOString();

  try {
    // Run health checks in parallel for efficiency
    const [mongodbHealth, chromadbHealth] = await Promise.all([
      checkMongoDBHealth(),
      checkChromaDBHealth(),
    ]);

    // Web server is healthy if we're responding
    const webHealth: ServiceHealth = {
      status: 'healthy',
      details: {
        uptime: process.uptime(),
      },
    };

    // Determine overall system health based on service health
    let overallStatus: HealthStatus = 'healthy';

    if (mongodbHealth.status === 'error' || chromadbHealth.status === 'error') {
      overallStatus = 'error';
    } else if (
      mongodbHealth.status === 'warning' ||
      chromadbHealth.status === 'warning'
    ) {
      overallStatus = 'warning';
    }

    const healthResponse: HealthCheckResponse = {
      status: overallStatus,
      environment,
      version,
      timestamp,
      services: {
        web: webHealth,
        mongodb: mongodbHealth,
        chromadb: chromadbHealth,
      },
    };

    // Set appropriate cache headers to prevent caching
    return NextResponse.json(healthResponse, {
      headers: {
        'Cache-Control': 'no-store, max-age=0',
      },
    });
  } catch (error) {
    console.error('Health check error:', error);

    const errorResponse: ErrorResponse = {
      status: 'error',
      environment,
      version,
      timestamp,
      error: (error as Error).message,
    };

    return NextResponse.json(errorResponse, { status: 500 });
  }
}

// app/api/admin/available-scripts/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../auth/[...nextauth]/route';
import fs from 'fs';
import path from 'path';

// Define types for script objects
interface ScriptItem {
  id: string;
  name: string;
  description: string;
  arguments?: string[];
  type: string;
  path: string;
  size: number;
  lastModified: Date;
}

interface ScriptsResponse {
  scripts: ScriptItem[];
  tests: ScriptItem[];
}

interface ErrorResponse {
  error: string;
}

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const scriptsDir = path.join(process.cwd(), 'scripts');
    const testsDir = path.join(process.cwd(), 'tests');

    // Get script files
    const scripts: ScriptItem[] = [];
    if (fs.existsSync(scriptsDir)) {
      const scriptFiles = fs.readdirSync(scriptsDir);

      for (const file of scriptFiles) {
        // Filter for JavaScript, TypeScript and PowerShell scripts
        if (
          file.endsWith('.js') ||
          file.endsWith('.ts') ||
          file.endsWith('.ps1')
        ) {
          const filePath = path.join(scriptsDir, file);
          const fileStats = fs.statSync(filePath);
          const fileContent = fs.readFileSync(filePath, 'utf8');

          // Simple metadata extraction (assuming metadata is in comments at the top)
          const descriptionMatch = fileContent.match(
            /\/\/\s*Description:\s*(.+)/,
          );
          const argsMatch = fileContent.match(/\/\/\s*Args:\s*(.+)/);

          // Determine script type based on extension
          let type = 'Unknown';
          if (file.endsWith('.js')) type = 'JavaScript';
          else if (file.endsWith('.ts')) type = 'TypeScript';
          else if (file.endsWith('.ps1')) type = 'PowerShell';

          scripts.push({
            id: file,
            name: file.replace(/\.[^/.]+$/, ''), // Remove extension
            description: descriptionMatch
              ? descriptionMatch[1]
              : 'No description available',
            arguments: argsMatch
              ? argsMatch[1].split(',').map(arg => arg.trim())
              : undefined,
            type,
            path: filePath,
            size: fileStats.size,
            lastModified: fileStats.mtime,
          });
        }
      }
    }

    // Get test files
    const tests: ScriptItem[] = [];
    if (fs.existsSync(testsDir)) {
      const testFiles = fs.readdirSync(testsDir);

      for (const file of testFiles) {
        // Filter for test files
        if (
          file.endsWith('.js') ||
          file.endsWith('.ts') ||
          file.endsWith('.ps1') ||
          file.endsWith('.test.js') ||
          file.endsWith('.test.ts')
        ) {
          const filePath = path.join(testsDir, file);
          const fileStats = fs.statSync(filePath);
          const fileContent = fs.readFileSync(filePath, 'utf8');

          // Simple metadata extraction
          const descriptionMatch = fileContent.match(
            /\/\/\s*Description:\s*(.+)/,
          );

          // Determine test type based on extension
          let type = 'Unknown';
          if (file.endsWith('.js') || file.endsWith('.test.js'))
            type = 'JavaScript';
          else if (file.endsWith('.ts') || file.endsWith('.test.ts'))
            type = 'TypeScript';
          else if (file.endsWith('.ps1')) type = 'PowerShell';

          tests.push({
            id: file,
            name: file.replace(/\.[^/.]+$/, ''), // Remove extension
            description: descriptionMatch
              ? descriptionMatch[1]
              : 'No description available',
            type,
            path: filePath,
            size: fileStats.size,
            lastModified: fileStats.mtime,
          });
        }
      }
    }

    return NextResponse.json({ scripts, tests });
  } catch (error) {
    console.error('Error in available-scripts API:', error);
    return NextResponse.json(
      { error: 'Failed to fetch available scripts' },
      { status: 500 },
    );
  }
}

