 The issue is likely that the `data-active` attribute isn't being set on your links. Here are a few solutions:

## Option 1: Manually set data-active based on current route

```tsx
'use client';

import { usePathname } from 'next/navigation';
import { AppShell, Container, Group, Text, UnstyledButton } from '@mantine/core';
import { Link } from 'next/link';
import classes from './Header.module.css';

export function Demo2() {
  const pathname = usePathname();

  const navItems = [
    { label: 'About', path: '/about' },
    { label: 'Blog', path: '/blog' },
    { label: 'Contact', path: '/contact' }
  ];

  return (
    <AppShell header={{ height: 70 }}>
      <AppShell.Header className={classes.header}>
        <Container size="xl" h="100%">
          <Group h="100%" justify="space-between" align="center">
            <Text size="xl" fw={700}>Your Site</Text>

            <Group gap="xl">
              {navItems.map((item) => (
                <UnstyledButton
                  key={item.path}
                  component={Link}
                  href={item.path}
                  data-active={pathname === item.path || undefined}
                  className={classes.link}
                >
                  {item.label}
                </UnstyledButton>
              ))}
            </Group>
          </Group>
        </Container>
      </AppShell.Header>
      <AppShell.Main>
        <div>Main content</div>
      </AppShell.Main>
    </AppShell>
  );
}
```

## Option 2: Use CSS class instead of data attribute

```css
/* Header.module.css */
.header a:hover,
.header a:focus,
.header a:focus-visible,
.header a.active {
  color: var(--mantine-color-peach-breeze-7);
}
```

```tsx
'use client';

import { usePathname } from 'next/navigation';
import { AppShell, Container, Group, Text, UnstyledButton } from '@mantine/core';
import { Link } from 'next/link';
import classes from './Header.module.css';

export function Demo2() {
  const pathname = usePathname();

  const navItems = [
    { label: 'About', path: '/about' },
    { label: 'Blog', path: '/blog' },
    { label: 'Contact', path: '/contact' }
  ];

  return (
    <AppShell header={{ height: 70 }}>
      <AppShell.Header className={classes.header}>
        <Container size="xl" h="100%">
          <Group h="100%" justify="space-between" align="center">
            <Text size="xl" fw={700}>Your Site</Text>

            <Group gap="xl">
              {navItems.map((item) => (
                <UnstyledButton
                  key={item.path}
                  component={Link}
                  href={item.path}
                  className={`${classes.link} ${pathname === item.path ? classes.active : ''}`}
                >
                  {item.label}
                </UnstyledButton>
              ))}
            </Group>
          </Group>
        </Container>
      </AppShell.Header>
      <AppShell.Main>
        <div>Main content</div>
      </AppShell.Main>
    </AppShell>
  );
}
```

## Option 3: Check exact data attribute syntax

Make sure your CSS selector matches exactly:

```css
/* This should work if data-active is set correctly */
.header a[data-active="true"] {
  color: var(--mantine-color-peach-breeze-7);
}

/* Or for any truthy value */
.header a[data-active] {
  color: var(--mantine-color-peach-breeze-7);
}
```

## Option 4: Debug - Check what's being rendered

Add this to see what's actually in the DOM:

```tsx
// Add this to your component to debug
useEffect(() => {
  console.log('Current pathname:', pathname);
  const links = document.querySelectorAll('.header a');
  links.forEach(link => {
    console.log('Link:', link.textContent, 'data-active:', link.getAttribute('data-active'));
  });
}, [pathname]);
```

## Option 5: Complete working example

```tsx
'use client';

import { usePathname } from 'next/navigation';
import { AppShell, Container, Group, Text } from '@mantine/core';
import Link from 'next/link';
import classes from './Header.module.css';

export function Demo2() {
  const pathname = usePathname();

  const navItems = [
    { label: 'About', path: '/about' },
    { label: 'Blog', path: '/blog' },
    { label: 'Contact', path: '/contact' }
  ];

  return (
    <AppShell header={{ height: 70 }}>
      <AppShell.Header className={classes.header}>
        <Container size="xl" h="100%">
          <Group h="100%" justify="space-between" align="center">
            <Text size="xl" fw={700}>Your Site</Text>

            <nav>
              <Group gap="xl">
                {navItems.map((item) => {
                  const isActive = pathname === item.path;
                  return (
                    <Link
                      key={item.path}
                      href={item.path}
                      className={classes.link}
                      data-active={isActive ? 'true' : undefined}
                    >
                      {item.label}
                    </Link>
                  );
                })}
              </Group>
            </nav>
          </Group>
        </Container>
      </AppShell.Header>
      <AppShell.Main>
        <div>Main content</div>
      </AppShell.Main>
    </AppShell>
  );
}
```

And the corresponding CSS:

```css
/* Header.module.css */
.header {
  border-bottom: 1px solid var(--mantine-color-gray-3);
}

.link {
  padding: 8px 16px;
  border-radius: var(--mantine-radius-md);
  text-decoration: none;
  color: inherit;
  font-weight: 500;
  transition: color 0.2s;
}

.link:hover,
.link:focus,
.link:focus-visible,
.link[data-active] {
  color: var(--mantine-color-peach-breeze-7);
}
```

The key points:
1. Make sure you're importing `usePathname` from `next/navigation`
2. Set `data-active` attribute based on the current route
3. Use the proper CSS selector syntax for the data attribute

Try Option 1 first - it should work with your existing CSS!

