  );
}
```

## Option 3: Convert to React Component with Gradient

If you can share the actual SVG path data, I can help you create a complete React component. But here's the general structure:

```tsx
interface GradientBrainIconProps {
  size?: number;
  colors?: string[];
}

function GradientBrainIcon({ size = 32, colors = ['#9c36b5', '#6c5ce7', '#a29bfe'] }: GradientBrainIconProps) {
  const gradientId = `brainGradient-${Math.random().toString(36).substr(2, 9)}`;

  return (
    <svg width={size} height={size} viewBox="0 0 100 100" fill="none">
      <defs>
        <linearGradient id={gradientId} x1="0%" y1="0%" x2="100%" y2="100%">
          {colors.map((color, index) => (
            <stop 
              key={index}
              offset={`${(index / (colors.length - 1)) * 100}%`} 
              stopColor={color} 
            />
          ))}
        </linearGradient>
      </defs>
      {/* Your SVG paths here with stroke={`url(#${gradientId})`} */}
    </svg>
  );
}
```

