## Option 2: CSS Filter on Existing SVG

```css
/* styles.module.css */
.svgGradient {
  filter: 
    hue-rotate(270deg) 
    saturate(2) 
    brightness(1.1)
    contrast(1.2);
}

/* Or create a more complex gradient effect */
.svgGradientComplex {
  position: relative;
}

.svgGradientComplex::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(45deg, #9c36b5, #6c5ce7, #a29bfe);
  mask: url('/path-to-your-brain-icon.svg') no-repeat center;
  mask-size: contain;
  -webkit-mask: url('/path-to-your-brain-icon.svg') no-repeat center;
  -webkit-mask-size: contain;
}

.svgGradientComplex svg {
  opacity: 0;
}
```

```tsx
import { Image } from '@mantine/core';
import styles from './styles.module.css';

function GradientBrainIcon() {
  return (
    <Image 
      src="/brain-icon.svg" 
      alt="Brain" 
      h={32} 
      w={32}
      className={styles.svgGradient}
    />
  );
}
```

## Option 3: Inline SVG with JavaScript Manipulation

```tsx
'use client';

import { useEffect, useRef } from 'react';

function GradientBrainIcon() {
  const svgRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (svgRef.current) {
      // Load the SVG and add gradient
      fetch('/brain-icon.svg')
        .then(response => response.text())
        .then(svgText => {
          if (svgRef.current) {
            // Parse the SVG
            const parser = new DOMParser();
            const svgDoc = parser.parseFromString(svgText, 'image/svg+xml');
            const svgElement = svgDoc.querySelector('svg');

            if (svgElement) {
              // Add gradient definition
              const defs = document.createElementNS('http://www.w3.org/2000/svg', 'defs');
              const gradient = document.createElementNS('http://www.w3.org/2000/svg', 'linearGradient');
              gradient.id = 'brainGradient';
              gradient.setAttribute('x1', '0%');
              gradient.setAttribute('y1', '0%');
              gradient.setAttribute('x2', '100%');
              gradient.setAttribute('y2', '100%');

              const colors = ['#9c36b5', '#6c5ce7', '#a29bfe'];
              colors.forEach((color, index) => {
                const stop = document.createElementNS('http://www.w3.org/2000/svg', 'stop');
                stop.setAttribute('offset', `${(index / (colors.length - 1)) * 100}%`);
                stop.setAttribute('stop-color', color);
                gradient.appendChild(stop);
              });

              defs.appendChild(gradient);
              svgElement.insertBefore(defs, svgElement.firstChild);

              // Apply gradient to all paths
              const paths = svgElement.querySelectorAll('path, circle, line, polyline, polygon');
              paths.forEach(path => {
                if (path.getAttribute('stroke')) {
                  path.setAttribute('stroke', 'url(#brainGradient)');
                }
                if (path.getAttribute('fill') && path.getAttribute('fill') !== 'none') {
                  path.setAttribute('fill', 'url(#brainGradient)');
                }
              });

              // Set size and replace content
              svgElement.setAttribute('width', '32');
              svgElement.setAttribute('height', '32');
              svgRef.current.innerHTML = '';
              svgRef.current.appendChild(svgElement);
            }
          }
        });
    }
  }, []);

  return <div ref={svgRef} style={{ width: 32, height: 32 }} />;
}
```

