      },
    },
  },
  sizes: {
    sm: {
      field: {
        h: '2rem',      // 32px
        fontSize: 'sm',
        px: '0.75rem',  // 12px
      },
    },
    md: {
      field: {
        h: '2.5rem',    // 40px
        fontSize: 'md',
        px: '1rem',     // 16px
      },
    },
    lg: {
      field: {
        h: '3rem',      // 48px
        fontSize: 'lg',
        px: '1.25rem',  // 20px
      },
    },
