  variants: {
    outline: {
      field: {
        bg: 'bg.primary',
      },
    },
    filled: {
      field: {
        bg: 'bg.secondary',
        borderColor: 'transparent',
        _hover: {
          bg: 'gray.100',
        },
        _focus: {
          bg: 'bg.primary',
          borderColor: 'brand.primary',
        },
      },
    },
  },
  defaultProps: {
    size: 'md',
    variant: 'outline',
  },
});

