export const theme = createSystem({
  config: {
    initialColorMode: 'light',
    useSystemColorMode: false,
  },
  tokens: {
    colors,
    semanticTokens,
    ...typography,
    space,
    sizes: space, // Reuse space values for sizes
    breakpoints,
    borders,
    radii,
  },
  recipes: {
    button: buttonRecipe,
    card: cardRecipe,
    input: inputRecipe,
