  styles: {
    global: defineStyle({
      body: {
        color: 'text.primary',
        bg: 'bg.primary',
        lineHeight: 'base',
        fontFamily: 'body',
      },
      // Base styles for heading elements
      'h1, h2, h3, h4, h5, h6': {
        fontFamily: 'heading',
        fontWeight: 'bold',
        lineHeight: 'shorter',
        color: 'text.primary',
      },
      h1: {
        fontSize: ['3xl', '4xl', '5xl'],
        mt: 8,
        mb: 4,
      },
      h2: {
        fontSize: ['2xl', '3xl'],
        mt: 6,
        mb: 3,
      },
      h3: {
        fontSize: ['xl', '2xl'],
        mt: 5,
        mb: 2,
      },
      // Add paragraph and link styles
      p: {
        mb: 4,
      },
      a: {
        color: 'text.link',
        _hover: {
          color: 'text.linkHover',
          textDecoration: 'underline',
        },
      },
    }),
  },
});

// Export the theme as default
export default theme;

