/* src/app/page.module.css */

/* Hero Section */
.hero {
  position: relative;
  background: linear-gradient(to right, var(--mantine-color-blue-9), var(--mantine-color-indigo-9));
  padding: 5rem 0;
  color: var(--mantine-color-white);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background-image: url('/images/hero-pattern.svg');
  background-size: cover;
  opacity: 0.1;
  z-index: 1;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 700px;
  padding: 2rem 0;
}

.heroTitle {
  font-size: 3.5rem;
  line-height: 1.2;
  font-weight: 800;
  margin-bottom: 1.5rem;
}

.highlight {
  color: var(--mantine-color-yellow-4);
  display: inline-block;
}

.heroText {
  font-size: 1.25rem;
  line-height: 1.6;
  margin-bottom: 2rem;
  opacity: 0.9;
}

.primaryButton {
  background: var(--mantine-color-yellow-4);
  color: var(--mantine-color-dark-9);
  transition: all 0.3s ease;
}

.primaryButton:hover {
  background: var(--mantine-color-yellow-5);
  transform: translateY(-3px);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.1);
}

.secondaryButton {
  border-color: var(--mantine-color-white);
  color: var(--mantine-color-white);
  transition: all 0.3s ease;
}

.secondaryButton:hover {
  background: rgba(255, 255, 255, 0.1);
  transform: translateY(-3px);
}

/* Section Titles */
.sectionTitle {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--mantine-color-dark-7);
  margin-bottom: 1rem;
}

/* Features Section */
.featureCard {
  height: 100%;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  border: 1px solid var(--mantine-color-gray-2);
}

.featureCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}

.featureIcon {
  color: var(--mantine-color-blue-6);
}

.featureTitle {
  color: var(--mantine-color-dark-7);
}

/* About Section */
.aboutSection {
  background-color: var(--mantine-color-gray-0);
}

.aboutTitle {
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--mantine-color-dark-7);
}

.aboutText {
  font-size: 1.1rem;
  line-height: 1.7;
  color: var(--mantine-color-dark-5);
}

.aboutImageContainer {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
}

.aboutImagePlaceholder {
  width: 100%;
  height: 400px;
  background-color: var(--mantine-color-gray-2);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Blog Section */
.blogCard {
  height: 100%;
  display: flex;
  flex-direction: column;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  border: 1px solid var(--mantine-color-gray-2);
}

.blogCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}

.blogImagePlaceholder {
  width: 100%;
  height: 200px;
  background-color: var(--mantine-color-gray-2);
  display: flex;
  align-items: center;
  justify-content: center;
}

.blogTitle {
  color: var(--mantine-color-dark-7);
  line-height: 1.4;
}

/* Testimonial Section */
.testimonialSection {
  background-color: var(--mantine-color-blue-0);
}

.testimonialCard {
  height: 100%;
  background-color: white;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.testimonialCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
}

.testimonialText {
  font-style: italic;
  line-height: 1.6;
  color: var(--mantine-color-dark-6);
}

.avatarPlaceholder {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background-color: var(--mantine-color-gray-3);
}

/* CTA Section */
.ctaCard {
  background: linear-gradient(to right, var(--mantine-color-blue-9), var(--mantine-color-indigo-9));
  color: white;
  border: none;
  padding: 3rem;
}

.ctaTitle {
  color: white;
  font-size: 2rem;
  font-weight: 700;
}

/* Placeholder for development */
.placeholderText {
  color: var(--mantine-color-gray-6);
  font-size: 0.875rem;
}

/* Responsive Adjustments */
@media (max-width: 768px) {
  .heroTitle {
    font-size: 2.5rem;
  }

  .heroText {
    font-size: 1rem;
  }

  .sectionTitle, .aboutTitle {
    font-size: 2rem;
  }

  .ctaTitle {
    font-size: 1.5rem;
  }
}

