import { createTheme, mergeMantineTheme, DEFAULT_THEME } from '@mantine/core';

/**
 * Hello Commerce theme configuration for Mantine 8.0.1
 * This theme extends the default Mantine theme with custom colors, fonts and other properties
 */
export const themeOverride = createTheme({
  /* Primary colors for the theme */
  primaryColor: 'blue',

  /* Color scheme settings */
  defaultRadius: 'md',

  /* Custom colors palette */
  colors: {
    // Override blue shade for primary color
    blue: [
      '#e6f7ff', // 0: lightest
      '#bae7ff',
      '#91d5ff',
      '#69c0ff',
      '#40a9ff',
      '#1890ff', // 5: primary
      '#096dd9',
      '#0050b3',
      '#003a8c',
      '#002766', // 9: darkest
    ],

    // Add a custom brand color
    brand: [
      '#fffbeb',
      '#fef3c7',
      '#fde68a',
      '#fcd34d',
      '#fbbf24',
      '#f59e0b', // primary brand
      '#d97706',
      '#b45309',
      '#92400e',
      '#78350f',
    ],
  },

  /* Typography settings */
  fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica, Arial, sans-serif',
  fontFamilyMonospace: 'Monaco, Courier, monospace',
  headings: {
    fontFamily: 'Inter, -apple-system, BlinkMacSystemFont, Segoe UI, Roboto, Helvetica, Arial, sans-serif',
    fontWeight: '700',
    sizes: {
      h1: { fontSize: '2.5rem', lineHeight: '1.2' },
      h2: { fontSize: '2rem', lineHeight: '1.3' },
      h3: { fontSize: '1.5rem', lineHeight: '1.4' },
      h4: { fontSize: '1.25rem', lineHeight: '1.5' },
      h5: { fontSize: '1rem', lineHeight: '1.5' },
      h6: { fontSize: '0.875rem', lineHeight: '1.5' },
    },
  },

  /* Other theme settings */
  respectReducedMotion: true,
  cursorType: 'pointer',
  primaryShade: { light: 6, dark: 8 },

  /* Component specific overrides */
  components: {
    Button: {
      defaultProps: {
        radius: 'md',
      },
      styles: {
        root: {
          fontWeight: 600,
        },
      },
    },
    Card: {
      defaultProps: {
        padding: 'lg',
        radius: 'md',
      },
      styles: {
        root: {
          transition: 'transform 0.3s ease, box-shadow 0.3s ease',
        },
      },
    },
    Container: {
      defaultProps: {
        size: 'lg',
      },
    },
    Title: {
      styles: {
        root: {
          '&:where(h1)': {
            fontSize: '2.5rem',
          },
          '&:where(h2)': {
            fontSize: '2rem',
          },
          '&:where(h3)': {
            fontSize: '1.5rem',
          },
        },
      },
    },
    Text: {
      styles: {
        root: {
          lineHeight: 1.6,
        },
      },
    },
  },

  /* Other theme settings */
  other: {
    // Custom values that can be accessed in components
    headerHeight: '80px',
    footerHeight: '250px',
    transitionTimingFunction: 'cubic-bezier(0.4, 0, 0.2, 1)',
    transitionDuration: '0.2s',
  },
});

// Merge with default theme
export const theme = mergeMantineTheme(DEFAULT_THEME, themeOverride);

export default theme;

