"use client";

import { useState } from 'react';
import { 
  Container, 
  Group, 
  Burger, 
  Drawer, 
  ScrollArea, 
  Divider, 
  UnstyledButton, 
  Text, 
  Button, 
  rem
} from '@mantine/core';
import { useDisclosure } from '@mantine/hooks';
import { IconShoppingCart } from '@tabler/icons-react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import classes from './Header.module.css';

// Navigation items
const links = [
  { link: '/', label: 'Home' },
  { link: '/about', label: 'About' },
  { link: '/shop', label: 'Shop' },
  { link: '/blog', label: 'Blog' },
  { link: '/contact', label: 'Contact' },
];

export function Header() {
  const [drawerOpened, { toggle: toggleDrawer, close: closeDrawer }] = useDisclosure(false);
  const pathname = usePathname();
  const [cartItemCount] = useState(0); // In a real app, this would come from a cart state/context

  const items = links.map((link) => {
    const isActive = pathname === link.link;

    return (
      <Link
        key={link.label}
        href={link.link}
        className={`${classes.link} ${isActive ? classes.linkActive : ''}`}
        onClick={() => closeDrawer()}
      >
        {link.label}
      </Link>
    );
  });

  return (
    <header className={classes.header}>
      <Container size="lg" className={classes.inner}>
        <Link href="/" className={classes.logo}>
          Hello Commerce
        </Link>

        <Group gap={5} visibleFrom="sm">
          {items}
        </Group>

        <Group visibleFrom="sm">
          <Link href="/shop/cart" className={classes.cartButton}>
            <IconShoppingCart size={20} stroke={1.5} />
            {cartItemCount > 0 && (
              <span className={classes.cartCount}>{cartItemCount}</span>
            )}
          </Link>

          <Button 
            component={Link} 
            href="/contact"
            radius="md" 
            className={classes.ctaButton}
          >
            Get Started
          </Button>
        </Group>

        <Burger
          opened={drawerOpened}
          onClick={toggleDrawer}
          hiddenFrom="sm"
          size="sm"
        />
      </Container>

      <Drawer
        opened={drawerOpened}
        onClose={closeDrawer}
        size="100%"
        padding="md"
        hiddenFrom="sm"
        zIndex={1000000}
      >
        <ScrollArea h={`calc(100vh - ${rem(60)})`} mx="-md">
          <Divider my="sm" color="gray.1" />

          <Link href="/" className={classes.mobileLogo} onClick={closeDrawer}>
            Hello Commerce
          </Link>

          <Divider my="sm" color="gray.1" />

          <div className={classes.mobileLinks}>
            {links.map((link) => (
              <UnstyledButton
                component={Link}
                key={link.label}
                href={link.link}
                className={classes.mobileLink}
                onClick={closeDrawer}
              >
                {link.label}
              </UnstyledButton>
            ))}
          </div>

          <Divider my="sm" color="gray.1" />

          <Group p="md" justify="space-between">
            <Link href="/shop/cart" className={classes.cartButtonMobile} onClick={closeDrawer}>
              <IconShoppingCart size={20} stroke={1.5} />
              <Text ml="xs">Cart {cartItemCount > 0 && `(${cartItemCount})`}</Text>
            </Link>

            <Button 
              component={Link} 
              href="/contact"
              radius="md" 
              fullWidth 
              className={classes.ctaButton}
              onClick={closeDrawer}
            >
              Get Started
            </Button>
          </Group>
        </ScrollArea>
      </Drawer>
    </header>
  );
}

export default Header;

