                  <Badge color="blue" variant="light">
                    {post.category}
                  </Badge>
                </Group>

                <Title order={3} className={classes.blogTitle}>
                  <Link href={`/blog/${post.slug}`} className={classes.blogTitleLink}>
                    {post.title}
                  </Link>
                </Title>

                <Text lineClamp={3} mt="sm" mb="md" className={classes.blogExcerpt}>
                  {post.excerpt}
                </Text>

                <div className={classes.blogMeta}>
                  <Group gap="xs">
                    <IconUser size={16} className={classes.metaIcon} />
                    <Text size="sm" c="dimmed">{post.author}</Text>
                  </Group>

                  <Group gap="xs">
                    <IconCalendar size={16} className={classes.metaIcon} />
                    <Text size="sm" c="dimmed">{post.date}</Text>
                  </Group>

                  <Group gap="xs">
                    <IconClock size={16} className={classes.metaIcon} />
                    <Text size="sm" c="dimmed">{post.readTime}</Text>
                  </Group>
                </div>

                <Button
                  component={Link}
                  href={`/blog/${post.slug}`}
                  variant="outline"
                  color="blue"
                  fullWidth
                  mt="md"
                  className={classes.readMoreButton}
                >
                  Read More
                </Button>
              </Card>
            ))}
          </SimpleGrid>
        ) : (
          <div className={classes.noResults}>
            <Title order={3}>No posts found</Title>
            <Text c="dimmed">
              Try adjusting your search or filter to find what you're looking for.
            </Text>
            <Button 
              variant="outline" 
              onClick={() => {
                setSearch('');
                setCategory('all');
              }}
              mt="md"
            >
              Clear filters
            </Button>
          </div>
        )}

        {/* Pagination */}
        {filteredPosts.length > postsPerPage && (
          <div className={classes.pagination}>
            <Pagination
              total={totalPages}
              value={currentPage}
              onChange={setCurrentPage}
              color="blue"
              radius="md"
            />
          </div>
        )}
      </Container>
    </div>
  );
}

