## Theme Configuration

### 3. Create Component Recipes

Recipes in Chakra UI 3.17 define the styling patterns for components.

#### `theme/recipes/button.ts`

Create a button recipe:

```typescript
// theme/recipes/button.ts
import { defineRecipe } from '@chakra-ui/react';

export const buttonRecipe = defineRecipe({
  base: {
    borderRadius: 'md',
    fontWeight: 'semibold',
    transition: 'all 0.2s',
  },
  variants: {
    visual: {
      solid: {
        bg: 'chakra-colors-{colorScheme}',
        color: 'white',
        _hover: {
          bg: 'chakra-colors-{colorScheme}-hover',
        },
        _active: {
          bg: 'chakra-colors-{colorScheme}-active',
        },
      },
      outline: {
        border: '1px solid',
        borderColor: 'chakra-colors-{colorScheme}',
        color: 'chakra-colors-{colorScheme}',
        _hover: {
          bg: 'rgba(0, 0, 0, 0.05)',
        },
      },
      ghost: {
        color: 'chakra-colors-{colorScheme}',
        _hover: {
          bg: 'rgba(0, 0, 0, 0.05)',
        },
      },
    },
    size: {
      sm: {
        fontSize: 'sm',
        px: '3',
        py: '1',
      },
      md: {
        fontSize: 'md',
        px: '4',
        py: '2',
      },
      lg: {
        fontSize: 'lg',
        px: '6',
        py: '3',
      },
    },
  },
  defaultVariants: {
    visual: 'solid',
    size: 'md',
  },
});
```

### 4. Create Main Theme Configuration

Now, let's create the main theme configuration file that brings everything together:

#### `theme/index.ts`

```typescript
// theme/index.ts
import { createSystem, defaultConfig } from '@chakra-ui/react';
import { tokens } from './tokens';
import { semanticTokens } from './semantic-tokens';
import { buttonRecipe } from './recipes/button';

export const system = createSystem(defaultConfig, {
  theme: {
    tokens,
    semanticTokens,
    recipes: {
      Button: buttonRecipe,
      // Add other component recipes here
    },
  },
});
```

## Provider Setup

### 5. Create Provider Component

Create a provider component to wrap your application:

#### `components/ui/provider.tsx`

```typescript
// components/ui/provider.tsx
'use client';

import { ChakraProvider } from '@chakra-ui/react';
import { system } from '@/theme';

export function Provider({ children }: { children: React.ReactNode }) {
  return <ChakraProvider value={system}>{children}</ChakraProvider>;
}
```

### 6. Set Up the Provider in Your App

Set up the Provider in your Next.js App Router layout:

#### `app/layout.tsx`

```typescript
// app/layout.tsx
import { Provider } from '@/components/ui/provider';
import './globals.css';

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>
        <Provider>{children}</Provider>
      </body>
    </html>
  );
}
```

## Component Implementation

### 7. Create UI Components Using Recipes

Now, let's create some UI components that use the theme configuration:

#### `components/ui/button.tsx`

```typescript
// components/ui/button.tsx
'use client';

import { Button as ChakraButton, type ButtonProps } from '@chakra-ui/react';

export const Button = (props: ButtonProps) => {
  return <ChakraButton colorScheme="brand" {...props} />;
};

// Variant components for convenience
export const PrimaryButton = (props: ButtonProps) => {
  return <Button colorScheme="brand" {...props} />;
};

export const OutlineButton = (props: ButtonProps) => {
  return <Button colorScheme="brand" visual="outline" {...props} />;
};

export const GhostButton = (props: ButtonProps) => {
  return <Button colorScheme="brand" visual="ghost" {...props} />;
};
```

