// app/components/ServerStatus.tsx
'use client';

import { useEffect, useState } from 'react';

interface StatusResponse {
  status: 'connected' | 'disconnected' | 'error';
  message?: string;
  error?: string;
  details?: any;
}

interface ServerStatuses {
  mongo: StatusResponse | null;
  chroma: StatusResponse | null;
}

export default function ServerStatus() {
  const [statuses, setStatuses] = useState<ServerStatuses>({
    mongo: null,
    chroma: null,
  });
  const [loading, setLoading] = useState(true);
  const [lastChecked, setLastChecked] = useState<Date | null>(null);

  const checkStatus = async () => {
    setLoading(true);

    try {
      // Check MongoDB status
      const mongoResponse = await fetch('/api/status/mongo');
      const mongoData = await mongoResponse.json();

      // Check ChromaDB status
      const chromaResponse = await fetch('/api/status/chroma');
      const chromaData = await chromaResponse.json();

      setStatuses({
        mongo: mongoData,
        chroma: chromaData,
      });
      setLastChecked(new Date());
    } catch (error) {
      console.error('Error checking server status:', error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    checkStatus();

    // Check status every 30 seconds
    const interval = setInterval(checkStatus, 30000);

    return () => clearInterval(interval);
  }, []);

  const getStatusColor = (status: string | undefined) => {
    switch (status) {
      case 'connected':
        return 'text-green-600';
      case 'disconnected':
        return 'text-red-600';
      case 'error':
        return 'text-orange-600';
      default:
        return 'text-gray-600';
    }
  };

  const getStatusIcon = (status: string | undefined) => {
    switch (status) {
      case 'connected':
        return '✅';
      case 'disconnected':
        return '❌';
      case 'error':
        return '⚠️';
      default:
        return '⏳';
    }
  };

  return (
    <div className="rounded-lg bg-white p-6 shadow-md">
      <div className="mb-4 flex items-center justify-between">
        <h2 className="text-xl font-semibold">Server Status</h2>
        <button
          onClick={checkStatus}
          disabled={loading}
          className="rounded bg-blue-500 px-3 py-1 text-sm text-white hover:bg-blue-600 disabled:opacity-50"
        >
          {loading ? 'Checking...' : 'Refresh'}
        </button>
      </div>

      <div className="space-y-4">
        {/* MongoDB Status */}
        <div className="flex items-center justify-between rounded border p-3">
          <div className="flex items-center space-x-3">
            <span className="text-2xl">{getStatusIcon(statuses.mongo?.status)}</span>
            <div>
              <h3 className="font-medium">MongoDB</h3>
              <p className={`text-sm ${getStatusColor(statuses.mongo?.status)}`}>
                {statuses.mongo?.status || 'Checking...'}
              </p>
            </div>
          </div>
          {statuses.mongo?.message && (
            <p className="text-sm text-gray-600">{statuses.mongo.message}</p>
          )}
        </div>

        {/* ChromaDB Status */}
        <div className="flex items-center justify-between rounded border p-3">
          <div className="flex items-center space-x-3">
            <span className="text-2xl">{getStatusIcon(statuses.chroma?.status)}</span>
            <div>
              <h3 className="font-medium">ChromaDB</h3>
              <p className={`text-sm ${getStatusColor(statuses.chroma?.status)}`}>
                {statuses.chroma?.status || 'Checking...'}
              </p>
            </div>
          </div>
          {statuses.chroma?.message && (
            <p className="text-sm text-gray-600">{statuses.chroma.message}</p>
          )}
        </div>
      </div>

      {lastChecked && (
        <p className="mt-4 text-xs text-gray-500">
          Last checked: {lastChecked.toLocaleTimeString()}
        </p>
      )}

      {/* Debug info - remove in production */}
      {process.env.NODE_ENV === 'development' && (
        <details className="mt-4">
          <summary className="cursor-pointer text-sm text-gray-600">Debug Info</summary>
          <pre className="mt-2 overflow-auto rounded bg-gray-100 p-2 text-xs">
            {JSON.stringify(statuses, null, 2)}
          </pre>
        </details>
      )}
    </div>
  );
}

// app/api/status/chroma/route.ts
import { NextResponse } from 'next/server';
import { ChromaClient } from 'chromadb';

export async function GET() {
  try {
    // Initialize ChromaDB client
    const client = new ChromaClient({
      path: process.env.CHROMA_URL || 'http://localhost:8000',
    });

    // Try to list collections as a health check
    const collections = await client.listCollections();

    return NextResponse.json({
      status: 'connected',
      message: `Connected to ChromaDB with ${collections.length} collections`,
      details: {
        url: process.env.CHROMA_URL || 'http://localhost:8000',
        collections: collections.length,
      }
    });
  } catch (error) {
    console.error('ChromaDB connection error:', error);

    return NextResponse.json({
      status: 'disconnected',
      error: error instanceof Error ? error.message : 'Unknown error',
      message: 'Failed to connect to ChromaDB',
    }, { status: 503 });
  }
}

// app/api/status/mongo/route.ts
import { NextResponse } from 'next/server';
import { connectToDatabase } from '@/lib/db/mongo';

export async function GET() {
  try {
    const { db, client } = await connectToDatabase();

    // Ping the database to check connection
    await db.admin().ping();

    // Get some basic stats
    const dbStats = await db.stats();

    return NextResponse.json({
      status: 'connected',
      message: 'MongoDB connection successful',
      details: {
        database: db.databaseName,
        collections: dbStats.collections,
        dataSize: `${(dbStats.dataSize / 1024 / 1024).toFixed(2)} MB`,
      }
    });
  } catch (error) {
    console.error('MongoDB connection error:', error);

    return NextResponse.json({
      status: 'disconnected',
      error: error instanceof Error ? error.message : 'Unknown error',
      message: 'Failed to connect to MongoDB',
    }, { status: 503 });
  }
}

