```typescript
// Get ChromaDB metrics
async function getChromaDBMetrics(): Promise<ServerMetrics> {
  try {
    const client = getChromaClient();
    const collections = await client.listCollections();

    let totalEmbeddings = 0;
    let version = 'unknown';

    // Get ChromaDB version from the API
    try {
      // ChromaDB exposes version info at the /api/v1 endpoint
      const response = await fetch('http://localhost:8000/api/v1', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (response.ok) {
        const data = await response.json();
        // ChromaDB returns version in the format: {"nanosecond":1234,"version":"0.4.22"}
        version = data.version || version;
      }
    } catch (err) {
      console.warn('Could not fetch ChromaDB version from API:', err);

      // Alternative: Try the heartbeat endpoint
      try {
        const heartbeat = await client.heartbeat();
        // heartbeat might contain version info
        if (heartbeat && typeof heartbeat === 'object' && 'version' in heartbeat) {
          version = heartbeat.version;
        }
      } catch (heartbeatErr) {
        console.warn('Heartbeat check failed:', heartbeatErr);
      }
    }

    // Count embeddings in each collection
    for (const collectionName of collections) {
      try {
        const collection = await client.getCollection({
          name: collectionName
        });

        const count = await collection.count();
        totalEmbeddings += count;
      } catch (err) {
        console.warn(`Error getting count for collection ${collectionName}:`, err);
      }
    }

    return {
      version,
      collections: collections.length,
      totalEmbeddings,
    };
  } catch (error) {
    console.error('Error getting ChromaDB metrics:', error);
    return {
      version: 'unknown',
      collections: 0,
      totalEmbeddings: 0,
    };
  }
}
