'use client';

import React, { useState, useEffect } from 'react';
import { 
  Server, 
  Database, 
  Users, 
  FileText, 
  Settings, 
  BarChart3, 
  MessageSquare,
  Shield,
  AlertCircle,
  CheckCircle,
  XCircle,
  Clock,
  HardDrive,
  Activity,
  Loader2,
  ChevronRight,
  X
} from 'lucide-react';

interface ServerStatus {
  postgresql: {
    status: 'connected' | 'disconnected' | 'error';
    version?: string;
    databases?: number;
    activeConnections?: number;
  };
  chromadb: {
    status: 'connected' | 'disconnected' | 'error';
    version?: string;
    collections?: number;
    totalEmbeddings?: number;
  };
  uptime: number;
  memoryUsage: {
    used: number;
    total: number;
    percentage: number;
  };
}

interface MenuItem {
  icon: React.ReactNode;
  label: string;
  href: string;
  description?: string;
  stats?: string;
}

export default function AdminDashboard() {
  const [serverStatus, setServerStatus] = useState<ServerStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedItem, setSelectedItem] = useState<MenuItem | null>(null);
  const [contentLoading, setContentLoading] = useState(false);

  const menuItems: MenuItem[] = [
    {
      icon: <Users className="w-5 h-5" />,
      label: 'User Management',
      href: '/admin/users',
      description: 'Manage user accounts and permissions',
      stats: serverStatus?.postgresql.status === 'connected' ? 'Active' : 'N/A'
    },
    {
      icon: <FileText className="w-5 h-5" />,
      label: 'Content Management',
      href: '/admin/content',
      description: 'Manage pages, posts, and media',
      stats: 'Documents'
    },
    {
      icon: <Database className="w-5 h-5" />,
      label: 'Database',
      href: '/admin/database',
      description: 'Database management and backups',
      stats: serverStatus?.postgresql.databases?.toString() || '0'
    },
    {
      icon: <MessageSquare className="w-5 h-5" />,
      label: 'Vector Store',
      href: '/admin/vectors',
      description: 'ChromaDB collections and embeddings',
      stats: serverStatus?.chromadb.collections?.toString() || '0'
    },
    {
      icon: <BarChart3 className="w-5 h-5" />,
      label: 'Analytics',
      href: '/admin/analytics',
      description: 'View site analytics and metrics',
      stats: 'Real-time'
    },
    {
      icon: <Shield className="w-5 h-5" />,
      label: 'Security',
      href: '/admin/security',
      description: 'Security settings and audit logs',
      stats: 'Secure'
    },
    {
      icon: <Settings className="w-5 h-5" />,
      label: 'Settings',
      href: '/admin/settings',
      description: 'System configuration and preferences',
      stats: 'Configure'
    }
  ];

  useEffect(() => {
    fetchServerStatus();
    const interval = setInterval(fetchServerStatus, 30000); // Refresh every 30 seconds
    return () => clearInterval(interval);
  }, []);

  const fetchServerStatus = async () => {
    try {
      const response = await fetch('/api/admin/server-status');
      if (!response.ok) throw new Error('Failed to fetch server status');
      const data = await response.json();
      setServerStatus(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch server status');
    } finally {
      setLoading(false);
    }
  };

  const handleItemClick = (item: MenuItem) => {
    setSelectedItem(item);
    setContentLoading(true);

    // Simulate content loading
    setTimeout(() => {
      setContentLoading(false);
    }, 500);
  };

  const formatUptime = (seconds: number) => {
    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    return `${days}d ${hours}h ${minutes}m`;
  };

  const formatBytes = (bytes: number) => {
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    if (bytes === 0) return '0 Bytes';
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return Math.round((bytes / Math.pow(1024, i)) * 100) / 100 + ' ' + sizes[i];
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'connected':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'disconnected':
        return <XCircle className="w-4 h-4 text-red-500" />;
      case 'error':
        return <AlertCircle className="w-4 h-4 text-yellow-500" />;
      default:
        return <Clock className="w-4 h-4 text-gray-500" />;
    }
  };

  // Placeholder content components for each section
  const renderContent = () => {
    if (!selectedItem) {
      return (
