                <X className="w-5 h-5 text-gray-500" />
              </button>
            </div>
          )}

          <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 min-h-[calc(100vh-12rem)]">
            {renderContent()}
          </div>
        </div>
      </div>
    </div>
  );
}

