import React, { useState } from 'react';
import {
  AppShell,
  Burger,
  Text,
  NavLink,
  Stack,
  Group,
  ActionIcon,
  Avatar,
  Menu,
  Divider,
  Badge,
  Box,
  MantineProvider,
  createTheme,
} from '@mantine/core';
import {
  IconDashboard,
  IconUsers,
  IconSettings,
  IconChartBar,
  IconBell,
  IconLogout,
  IconUser,
  IconChevronRight,
  IconHome,
} from '@tabler/icons-react';

// Custom theme override
const dashboardTheme = createTheme({
  primaryColor: 'blue',
  other: {
    brand: {
      50: '#f0f9ff',
      100: '#e0f2fe',
      200: '#bae6fd',
      300: '#7dd3fc',
      400: '#38bdf8',
      500: '#0ea5e9',
      600: '#0284c7',
      700: '#0369a1',
      800: '#075985',
      900: '#0c4a6e',
    },
  },
});

// Navigation items configuration
const navigationItems = [
  { label: 'Dashboard', icon: IconDashboard, href: '/dashboard', badge: null },
  {
    label: 'Analytics',
    icon: IconChartBar,
    href: '/admin/server-status',
    badge: 'New',
  },
  { label: 'Users', icon: IconUsers, href: '/users', badge: null },
  { label: 'Settings', icon: IconSettings, href: '/settings', badge: null },
];

interface DashboardLayoutProps {
  children: React.ReactNode;
  activeItem?: string;
}

export function DashboardLayout({
  children,
  activeItem = 'Dashboard',
}: DashboardLayoutProps) {
  const [opened, setOpened] = useState(false);

  const navItems = navigationItems.map(item => (
    <NavLink
      key={item.label}
      href={item.href}
      label={item.label}
      leftSection={<item.icon size={16} stroke={1.5} />}
      rightSection={
        item.badge ? (
          <Badge size="xs" variant="filled" color="red">
            {item.badge}
          </Badge>
        ) : (
          <IconChevronRight size={12} stroke={1.5} />
        )
      }
      active={activeItem === item.label}
      onClick={() => setOpened(false)}
      style={{
        borderRadius: '8px',
        margin: '4px 8px',
      }}
    />
  ));

  return (
    <MantineProvider theme={dashboardTheme}>
      <AppShell
        header={{ height: 70 }}
        navbar={{
          width: { sm: 200, lg: 300 },
          collapsed: { mobile: !opened },
          breakpoint: 'sm',
