'use client';

import React, { useState } from 'react';
import {
  AppShell,
  Burger,
  Text,
  NavLink,
  Stack,
  Group,
  ActionIcon,
  Avatar,
  Menu,
  Divider,
  Badge,
  Box,
  MantineProvider,
  createTheme,
} from '@mantine/core';
import {
  IconDashboard,
  IconUsers,
  IconSettings,
  IconChartBar,
  IconBell,
  IconLogout,
  IconUser,
  IconChevronRight,
  IconHome,
} from '@tabler/icons-react';

const dashboardTheme = createTheme({
  primaryColor: 'blue',
  other: {
    brand: {
      50: '#f0f9ff',
      100: '#e0f2fe',
      200: '#bae6fd',
      300: '#7dd3fc',
      400: '#38bdf8',
      500: '#0ea5e9',
      600: '#0284c7',
      700: '#0369a1',
      800: '#075985',
      900: '#0c4a6e',
    },
  },
});

const navigationItems = [
  { label: 'Dashboard', icon: IconDashboard, href: '/dashboard', badge: null },
  {
    label: 'Analytics',
    icon: IconChartBar,
    href: '/admin/server-status',
    badge: 'New',
  },
  { label: 'Users', icon: IconUsers, href: '/users', badge: null },
  { label: 'Settings', icon: IconSettings, href: '/settings', badge: null },
];

export default function DashboardLayout({ 
  children 
}: { 
  children: React.ReactNode 
}) {
  const [opened, setOpened] = useState(false);

  const navItems = navigationItems.map(item => (
    <NavLink
      key={item.label}
      href={item.href}
      label={item.label}
      leftSection={<item.icon size={16} stroke={1.5} />}
      rightSection={
        item.badge ? (
          <Badge size="xs" variant="filled" color="red">
            {item.badge}
          </Badge>
        ) : (
          <IconChevronRight size={12} stroke={1.5} />
        )
      }
      active={item.label === 'Dashboard'}
      onClick={() => setOpened(false)}
      style={{
        borderRadius: '8px',
        margin: '4px 8px',
      }}
    />
  ));

  return (
    <MantineProvider theme={dashboardTheme}>
      <div
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          zIndex: 9999,
          backgroundColor: '#f8fafc',
          overflow: 'hidden',
        }}
      >
        <AppShell
          header={{ height: 70 }}
          navbar={{
            width: { sm: 200, lg: 300 },
            collapsed: { mobile: !opened },
            breakpoint: 'sm',
          }}
          padding="md"
          style={{ backgroundColor: '#f8fafc', height: '100%' }}
        >
          <AppShell.Header>
            <Group h="100%" px="md" justify="space-between">
              <Group>
                <Burger
                  opened={opened}
                  onClick={() => setOpened(o => !o)}
                  hiddenFrom="sm"
                  size="sm"
                />
                <Group gap="xs">
                  <IconHome size={24} color="#0284c7" />
                  <Text size="xl" fw={600} c="#0369a1">
                    Dashboard
                  </Text>
                </Group>
              </Group>

              <Group>
                <ActionIcon variant="light" color="gray" size="lg">
                  <IconBell size={18} />
                </ActionIcon>

                <Menu shadow="md" width={200}>
                  <Menu.Target>
                    <ActionIcon variant="light" size="lg">
                      <Avatar size="sm" color="blue">
                        JD
                      </Avatar>
                    </ActionIcon>
                  </Menu.Target>

                  <Menu.Dropdown>
                    <Menu.Label>Account</Menu.Label>
                    <Menu.Item leftSection={<IconUser size={14} />}>
                      Profile
                    </Menu.Item>
                    <Menu.Item leftSection={<IconSettings size={14} />}>
                      Settings
                    </Menu.Item>
                    <Menu.Divider />
                    <Menu.Item leftSection={<IconLogout size={14} />} color="red">
                      Logout
                    </Menu.Item>
                  </Menu.Dropdown>
                </Menu>
              </Group>
            </Group>
          </AppShell.Header>

          <AppShell.Navbar
            p="md"
            style={{
              backgroundColor: '#ffffff',
              borderRight: '1px solid #e2e8f0',
            }}
          >
            <AppShell.Section>
              <Text size="xs" fw={500} c="dimmed" tt="uppercase" mb="md">
                Navigation
              </Text>
            </AppShell.Section>

            <AppShell.Section grow>
              <Stack gap={4}>{navItems}</Stack>
            </AppShell.Section>

            <AppShell.Section>
              <Divider mb="md" />
              <Box
                p="xs"
                style={{
                  backgroundColor: '#f8f9fa',
                  borderRadius: '6px',
                }}
              >
                <Text size="xs" c="dimmed" ta="center">
                  Version 1.0.0
                </Text>
              </Box>
            </AppShell.Section>
          </AppShell.Navbar>

          <AppShell.Main>{children}</AppShell.Main>
        </AppShell>
      </div>
    </MantineProvider>
  );
}

# Dashboard File Structure

Create this folder structure in your `app` directory:

```
app/
├── dashboard/
│   ├── layout.tsx          # Your current layout file
│   ├── page.tsx            # Your current dashboard page
│   ├── analytics/
│   │   └── page.tsx        # Analytics page
│   ├── users/
│   │   └── page.tsx        # Users page
│   └── settings/
│       └── page.tsx        # Settings page
```

Each page will automatically render within your dashboard layout when the user navigates to that route.

## Example Page Files:

### app/dashboard/analytics/page.tsx
```tsx
'use client';

import { Card, Text, Title, Stack } from '@mantine/core';

export default function Analytics() {
  return (
    <Stack gap="lg">
      <Title order={2}>Analytics</Title>
      <Card withBorder padding="lg">
        <Text>Analytics content goes here...</Text>
      </Card>
    </Stack>
  );
}
```

### app/dashboard/users/page.tsx
```tsx
'use client';

import { Card, Text, Title, Stack } from '@mantine/core';

export default function Users() {
  return (
    <Stack gap="lg">
      <Title order={2}>Users</Title>
      <Card withBorder padding="lg">
        <Text>Users management content goes here...</Text>
      </Card>
    </Stack>
  );
}
```

### app/dashboard/settings/page.tsx
```tsx
'use client';

import { Card, Text, Title, Stack } from '@mantine/core';

export default function Settings() {
  return (
    <Stack gap="lg">
      <Title order={2}>Settings</Title>
      <Card withBorder padding="lg">
        <Text>Settings content goes here...</Text>
      </Card>
    </Stack>
  );
}
```

