'use client';

import { Box } from '@mantine/core';
import Header from '../../components/Header';
import Footer from '../../components/Footer';
import { Children, cloneElement, isValidElement, ReactNode } from 'react';

export default function SiteLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  // Extract Hero component if it exists
  let heroComponent: ReactNode = null;
  let otherContent: ReactNode[] = [];

  Children.forEach(children, (child) => {
    if (isValidElement(child) && child.type?.name === 'Hero') {
      heroComponent = child;
    } else {
      otherContent.push(child);
    }
  });

  return (
    <Box style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>
      {/* Fixed Header */}
      <Box style={{ 
        position: 'fixed', 
        top: 0, 
        left: 0, 
        right: 0, 
        zIndex: 100,
        backgroundColor: 'white',
        borderBottom: '1px solid #e2e8f0'
      }}>
        <Header />
      </Box>

      {/* Fixed Hero Section (if exists) */}
      {heroComponent && (
        <Box style={{
          position: 'fixed',
          top: '100px', // Adjust based on your header height
          left: 0,
          right: 0,
          zIndex: 50,
          height: '300px', // Adjust based on your hero height
        }}>
          {heroComponent}
        </Box>
      )}

      {/* Content with appropriate margin */}
      <Box 
        component="main" 
        style={{ 
          marginTop: heroComponent ? '400px' : '100px', // Header + Hero or just Header
          flex: 1
        }}
      >
        {otherContent}
      </Box>

      <Footer />
    </Box>
  );
}

