'use client';

import React, { useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { signOut } from 'next-auth/react';
import {
  AppShell,
  Burger,
  Text,
  NavLink,
  Stack,
  Group,
  ActionIcon,
  Avatar,
  Menu,
  Divider,
  Badge,
  Box,
  MantineProvider,
  createTheme,
} from '@mantine/core';
import {
  IconDashboard,
  IconUsers,
  IconSettings,
  IconChartBar,
  IconBell,
  IconLogout,
  IconUser,
  IconChevronRight,
  IconHome,
  IconPin,
} from '@tabler/icons-react';

const dashboardTheme = createTheme({
  primaryColor: 'blue',
  other: {
    brand: {
      50: '#f0f9ff',
      100: '#e0f2fe',
      200: '#bae6fd',
      300: '#7dd3fc',
      400: '#38bdf8',
      500: '#0ea5e9',
      600: '#0284c7',
      700: '#0369a1',
      800: '#075985',
      900: '#0c4a6e',
    },
  },
});

const navigationItems = [
  {
    label: 'Dashboard',
    icon: IconDashboard,
    href: '/admin/dashboard',
    badge: null,
  },
  {
    label: 'Posts',
    icon: IconPin,
    href: '/admin/dashboard/editor',
    badge: null,
  },
  {
    label: 'Analytics',
    icon: IconChartBar,
    href: '/admin/dashboard/analytics',
    badge: 'New',
  },
  {
    label: 'Users',
    icon: IconUsers,
    href: '/admin/dashboard/users',
    badge: null,
  },
  {
    label: 'Settings',
    icon: IconSettings,
    href: '/admin/dashboard/settings',
    badge: null,
  },
];

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [opened, setOpened] = useState(false);
  const pathname = usePathname();
  const router = useRouter();

  const handleLogout = async () => {
    try {
      await signOut({ 
        redirect: false,
        callbackUrl: '/' 
      });
      router.push('/');
    } catch (error) {
      console.error('Logout error:', error);
    }
  };

  const navItems = navigationItems.map(item => (
    <NavLink
      key={item.label}
      href={item.href}
      label={item.label}
      leftSection={<item.icon size={16} stroke={1.5} />}
