        right: 0,
        bottom: 0,
        zIndex: 9999,
        backgroundColor: '#f8fafc',
        overflow: 'hidden',
      }}
    >
      <AppShell
        header={{ height: 70 }}
        navbar={{
          width: { sm: 200, lg: 300 },
          collapsed: { mobile: !opened },
          breakpoint: 'sm',
        }}
        padding="md"
        style={{ backgroundColor: '#f8fafc', height: '100%' }}
