// scripts/create-admin.ts
import { connectToDatabase } from "../lib/db/mongo";
import { z } from "zod";
import crypto from "crypto";
import { ObjectId } from "mongodb";
import { UserRole } from "../types/user";

// Schema for admin user input validation
const AdminInputSchema = z.object({
  email: z.string().email("Invalid email address"),
  name: z.string().min(2, "Name must be at least 2 characters"),
  password: z.string().min(8, "Password must be at least 8 characters"),
  role: z.enum(["admin", "user"]).default("admin")
});

type AdminInputData = z.infer<typeof AdminInputSchema>;

interface AdminDocument extends Omit<AdminInputData, "password"> {
  _id?: ObjectId;
  passwordHash: string;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Hash a password with a random salt using PBKDF2
 */
function hashPassword(password: string): string {
  const salt = crypto.randomBytes(16).toString("hex");
  const hash = crypto
    .pbkdf2Sync(password, salt, 1000, 64, "sha512")
    .toString("hex");
  return `${salt}:${hash}`;
}

async function createAdminUser() {
  // Hard-code admin details for this script
  // In a real app, you might want to accept these as command line arguments
  const adminData: AdminInputData = {
    email: "admin@example.com",
    name: "Admin User",
    password: "adminpassword123",
    role: "admin"
  };

  try {
    // Validate input data
    AdminInputSchema.parse(adminData);

    // Connect to MongoDB
    const { db } = await connectToDatabase();
    const usersCollection = db.collection("users");

    // Check if user already exists
    const existingUser = await usersCollection.findOne({ 
      email: adminData.email 
    });

    if (existingUser) {
      console.log(`User with email ${adminData.email} already exists.`);
      process.exit(0);
    }

    // Hash the password
    const passwordHash = hashPassword(adminData.password);

    // Create admin document
    const adminDoc: AdminDocument = {
      email: adminData.email,
      name: adminData.name,
      role: adminData.role,
      passwordHash,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    // Insert admin user into database
    const result = await usersCollection.insertOne(adminDoc);

    if (result.acknowledged) {
      console.log(`Admin user created successfully with ID: ${result.insertedId}`);
      console.log(`Email: ${adminData.email}`);
      console.log(`Password: ${adminData.password}`);
    } else {
      console.error("Failed to create admin user.");
    }
  } catch (error) {
    if (error instanceof z.ZodError) {
      console.error("Invalid admin data:");
      error.errors.forEach(err => {
        console.error(`- ${err.path.join(".")}: ${err.message}`);
      });
    } else {
      console.error("Error creating admin user:", error);
    }
    process.exit(1);
  }
}

// Run the function
createAdminUser()
  .catch(console.error)
  .finally(() => {
    console.log("Admin user creation process complete.");
    process.exit(0);
  });

'use client';

import { useState, FormEvent } from 'react';
import { signIn } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import { z } from 'zod';

// Form validation schema
const loginSchema = z.object({
  email: z.string().email('Invalid email address'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
});

type LoginFormData = z.infer<typeof loginSchema>;
type FieldErrors = Partial<Record<keyof LoginFormData, string>>;

export default function AdminLogin() {
  const router = useRouter();
  const [formData, setFormData] = useState<LoginFormData>({
    email: '',
    password: '',
  });
  const [errors, setErrors] = useState<FieldErrors>({});
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [loginError, setLoginError] = useState<string>('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setErrors({});
    setLoginError('');

    try {
      // Validate form data
      loginSchema.parse(formData);

      setIsLoading(true);

      // Attempt login
      const result = await signIn('credentials', {
        redirect: false,
        email: formData.email,
        password: formData.password,
      });

      if (result?.error) {
        setLoginError('Invalid email or password');
        setIsLoading(false);
        return;
      }

      // Redirect to admin dashboard on success
      router.push('/admin/dashboard');
    } catch (error) {
      if (error instanceof z.ZodError) {
        const fieldErrors: FieldErrors = {};
        error.errors.forEach((err) => {
          if (err.path[0]) {
            fieldErrors[err.path[0] as keyof LoginFormData] = err.message;
          }
        });
        setErrors(fieldErrors);
      } else {
        setLoginError('An unexpected error occurred');
        console.error(error);
      }
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100">
      <div className="bg-white p-8 rounded-lg shadow-md w-full max-w-md">
        <h1 className="text-2xl font-bold mb-6 text-center">Admin Login</h1>

        {loginError && (
          <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
            {loginError}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label
              htmlFor="email"
              className="block text-gray-700 font-medium mb-2"
            >
              Email
            </label>
            <input
              id="email"
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className={`w-full px-3 py-2 border rounded-md ${
                errors.email ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.email && (
              <p className="text-red-500 text-sm mt-1">{errors.email}</p>
            )}
          </div>

          <div className="mb-6">
            <label
              htmlFor="password"
              className="block text-gray-700 font-medium mb-2"
            >
              Password
            </label>
            <input
              id="password"
              type="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className={`w-full px-3 py-2 border rounded-md ${
                errors.password ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {errors.password && (
              <p className="text-red-500 text-sm mt-1">{errors.password}</p>
            )}
          </div>

          <button
            type="submit"
            disabled={isLoading}
            className={`w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 transition-colors ${
              isLoading ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            {isLoading ? 'Logging in...' : 'Login'}
          </button>
        </form>
      </div>
    </div>
  );
}

'use client';

import { useSession } from 'next-auth/react';
import { redirect, usePathname } from 'next/navigation';
import { SessionProvider } from 'next-auth/react';

export default function AdminLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <SessionProvider>
      <AdminProtected>{children}</AdminProtected>
    </SessionProvider>
  );
}

function AdminProtected({ children }: { children: React.ReactNode }) {
  const { data: session, status } = useSession();
  const pathname = usePathname();

  if (status === 'loading') {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="h-8 w-8 animate-spin rounded-full border-b-2 border-gray-900"></div>
      </div>
    );
  }

  // Allow unauthenticated access to login page
  if (pathname === '/admin/login') {
    // If user is already logged in, redirect to dashboard
    if (session) {
      redirect('/admin/dashboard');
    }
    return <>{children}</>;
  }

  // Require authentication for all other admin routes
  if (!session) {
    redirect('/admin/login');
  }

  // Check for admin role with proper type safety
  if (!session.user || session.user.role !== 'admin') {
    redirect('/access-denied');
  }

  return <>{children}</>;
}

// types/next-auth.d.ts
import { DefaultSession, DefaultUser } from "next-auth";
import { JWT } from "next-auth/jwt";

declare module "next-auth" {
  /**
   * Returned by useSession, getSession and received as a prop by SessionProvider
   */
  interface Session {
    user: {
      id: string;
      role: 'admin' | 'user';
    } & DefaultSession["user"];
  }

  /**
   * The shape of the user object returned in the OAuth providers' callback
   */
  interface User extends DefaultUser {
    role: 'admin' | 'user';
  }
}

declare module "next-auth/jwt" {
  /**
   * The shape of the JWT token
   */
  interface JWT {
    id?: string;
    role?: 'admin' | 'user';
  }
}

// app/api/auth/[...nextauth]/route.ts
import NextAuth, { NextAuthOptions } from 'next-auth';
import CredentialsProvider from 'next-auth/providers/credentials';
import { connectToDatabase } from '@/lib/db/mongo';
import crypto from 'crypto';

// Verify password function
function verifyPassword(
  storedPassword: string,
  suppliedPassword: string,
): boolean {
  const [salt, hash] = storedPassword.split(':');
  const suppliedHash = crypto
    .pbkdf2Sync(suppliedPassword, salt, 1000, 64, 'sha512')
    .toString('hex');
  return hash === suppliedHash;
}

export const authOptions: NextAuthOptions = {
  providers: [
    CredentialsProvider({
      name: 'Credentials',
      credentials: {
        email: { label: 'Email', type: 'email' },
        password: { label: 'Password', type: 'password' },
      },
      async authorize(credentials) {
        if (!credentials) {
          return null;
        }

        try {
          const { db } = await connectToDatabase();

          // Find user
          const user = await db.collection('users').findOne({
            email: credentials.email,
          });

          if (!user) {
            return null;
          }

          // Check password
          const isPasswordValid = verifyPassword(
            user.passwordHash,
            credentials.password,
          );

          if (!isPasswordValid) {
            return null;
          }

          // Return user data
          return {
            id: user._id.toString(),
            email: user.email,
            name: user.name,
            role: user.role as 'admin' | 'user',
          };
        } catch (error) {
          console.error('Auth error:', error);
          return null;
        }
      },
    }),
  ],
  session: {
    strategy: 'jwt',
    maxAge: 24 * 60 * 60, // 24 hours
  },
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.id = user.id;
        token.role = user.role;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        session.user.id = token.id as string;
        session.user.role = token.role as 'admin' | 'user';
      }
      return session;
    },
  },
  pages: {
    signIn: '/admin/login',
    error: '/admin/error',
  },
  secret: process.env.NEXTAUTH_SECRET,
};

// Export the NextAuth handler for App Router
const handler = NextAuth(authOptions);
export { handler as GET, handler as POST };

import Link from 'next/link';

export default function AccessDenied() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-100">
      <div className="w-full max-w-md rounded-lg bg-white p-8 text-center shadow-lg">
        <h1 className="mb-4 text-2xl font-bold text-red-600">Access Denied</h1>
        <p className="mb-6 text-gray-600">
          You don't have permission to access this page. Please contact an
          administrator if you believe this is an error.
        </p>
        <Link
          href="/"
          className="inline-block rounded-md bg-blue-600 px-4 py-2 text-white transition-colors hover:bg-blue-700"
        >
          Return to Home
        </Link>
      </div>
    </div>
  );
}

'use client';

import { useSession } from 'next-auth/react';
import Link from 'next/link';
import { useState, useEffect } from 'react';

// Define types for dashboard statistics
interface DashboardStats {
  serverHealth: 'healthy' | 'warning' | 'error' | 'loading';
  databaseSize: number;
  totalCollections: number;
  scriptsAvailable: number;
}

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchStats = async () => {
