// Define types for health check response
type HealthStatus = 'healthy' | 'warning' | 'error';

interface ServiceHealth {
  status: HealthStatus;
  details?: Record<string, any>;
}

interface HealthCheckResponse {
  status: HealthStatus;
  environment: string;
  version: string;
  timestamp: string;
  services: {
    web: ServiceHealth;
    mongodb: ServiceHealth;
    chromadb: ServiceHealth;
  };
}

interface ErrorResponse {
  status: 'error';
  environment: string;
  version: string;
  timestamp: string;
  error: string;
}

/**
 * Check MongoDB connection health
 */
async function checkMongoDBHealth(): Promise<ServiceHealth> {
  try {
    const { db } = await connectToDatabase();

    // Ping MongoDB to verify connection
    await db.command({ ping: 1 });

    // Get some basic stats
    const serverStatus = await db.command({ serverStatus: 1 });

    return {
      status: 'healthy',
      details: {
        version: serverStatus.version,
        uptime: serverStatus.uptime,
        connections: serverStatus.connections.current
      }
    };
  } catch (error) {
    console.error("MongoDB health check failed:", error);
    return {
      status: 'error',
      details: {
        message: (error as Error).message
      }
    };
  }
}

/**
 * Check ChromaDB connection health
 */
async function checkChromaDBHealth(): Promise<ServiceHealth> {
  try {
    // Try to connect to ChromaDB heartbeat endpoint
    const response = await fetch("http://localhost:8000/api/v1/heartbeat", {
      method: "GET",
      headers: {
        "Content-Type": "application/json"
      },
      // Add timeout to avoid hanging
      signal: AbortSignal.timeout(2000) // 2-second timeout
    });

    if (!response.ok) {
      throw new Error(`ChromaDB returned status: ${response.status}`);
    }

    // Get collections to add detail
    const collectionsResponse = await fetch("http://localhost:8000/api/v1/collections", {
      method: "GET",
      headers: {
        "Content-Type": "application/json"
      }
    });

    let collections: any[] = [];
    if (collectionsResponse.ok) {
      collections = await collectionsResponse.json();
    }

    return {
      status: 'healthy',
      details: {
        collectionCount: Array.isArray(collections) ? collections.length : 0
      }
    };
  } catch (error) {
    console.error("ChromaDB health check failed:", error);
    return {
      status: 'error',
      details: {
        message: (error as Error).message
      }
    };
  }
}

/**
 * Health check API endpoint
 */
export async function GET(req: NextRequest): Promise<NextResponse> {
  const environment = process.env.NODE_ENV || "development";
  const version = process.env.APP_VERSION || "1.0.0";
  const timestamp = new Date().toISOString();

  try {
    // Run health checks in parallel for efficiency
    const [mongodbHealth, chromadbHealth] = await Promise.all([
      checkMongoDBHealth(),
      checkChromaDBHealth()
    ]);

    // Web server is healthy if we're responding
    const webHealth: ServiceHealth = {
      status: 'healthy',
      details: {
        uptime: process.uptime()
      }
    };

    // Determine overall system health based on service health
    let overallStatus: HealthStatus = 'healthy';

    if (mongodbHealth.status === 'error' || chromadbHealth.status === 'error') {
      overallStatus = 'error';
    } else if (mongodbHealth.status === 'warning' || chromadbHealth.status === 'warning') {
      overallStatus = 'warning';
    }

    const healthResponse: HealthCheckResponse = {
      status: overallStatus,
      environment,
      version,
      timestamp,
      services: {
        web: webHealth,
        mongodb: mongodbHealth,
        chromadb: chromadbHealth
      }
    };

    // Set appropriate cache headers to prevent caching
    return NextResponse.json(healthResponse, {
      headers: {
        'Cache-Control': 'no-store, max-age=0'
      }
    });
  } catch (error) {
    console.error("Health check error:", error);

    const errorResponse: ErrorResponse = {
      status: 'error',
      environment,
      version,
      timestamp,
      error: (error as Error).message
    };

    return NextResponse.json(errorResponse, { status: 500 });
  }
}

// Description: Clean up old data in the database
// Args: dryRun=true, olderThan=30
import { connectToDatabase } from "../lib/db/mongo";

/**
 * This script cleans up old data in MongoDB collections
 * It can be run with the following arguments:
 * - dryRun: Set to true to just show what would be deleted without actually deleting
 * - olderThan: Delete records older than this many days (default: 30)
 */

// Parse command line arguments
const args = process.argv.slice(2);
const dryRun = args.find(arg => arg.includes('dryRun'))?.split('=')[1] === 'true';
const olderThan = parseInt(args.find(arg => arg.includes('olderThan'))?.split('=')[1] || '30', 10);

// Calculate the date threshold
const thresholdDate = new Date();
thresholdDate.setDate(thresholdDate.getDate() - olderThan);

interface CleanupResult {
  collection: string;
  itemsMatched: number;
  itemsDeleted: number;
}

async function cleanupCollection(
  db: any, 
  collectionName: string, 
  dateField: string = 'updatedAt',
  additionalQuery: Record<string, any> = {}
): Promise<CleanupResult> {
  console.log(`Processing collection: ${collectionName}`);
  const collection = db.collection(collectionName);

  // Build the query
  const query = {
    [dateField]: { $lt: thresholdDate },
    ...additionalQuery
  };

  // Count how many documents match the query
  const matchingDocs = await collection.countDocuments(query);
  console.log(`Found ${matchingDocs} documents older than ${olderThan} days in ${collectionName}`);

  // Delete the documents if not a dry run
  let deleted = 0;
  if (!dryRun && matchingDocs > 0) {
    const result = await collection.deleteMany(query);
    deleted = result.deletedCount || 0;
    console.log(`Deleted ${deleted} documents from ${collectionName}`);
  } else if (dryRun && matchingDocs > 0) {
    console.log(`Would delete ${matchingDocs} documents from ${collectionName} (dry run)`);
  }

  return {
    collection: collectionName,
    itemsMatched: matchingDocs,
    itemsDeleted: deleted
  };
}

async function main() {
  console.log(`Running database cleanup (${dryRun ? 'DRY RUN' : 'ACTUAL DELETE'})`);
  console.log(`Cleaning up records older than ${olderThan} days (before ${thresholdDate.toISOString()})`);

  try {
    const { db } = await connectToDatabase();
    const results: CleanupResult[] = [];

    // Clean up old sessions that are completed or archived
    results.push(await cleanupCollection(db, 'sessions', 'updatedAt', {
      status: { $in: ['completed', 'archived'] }
    }));

    // Clean up any other collections as needed
    // results.push(await cleanupCollection(db, 'logs', 'createdAt'));

    // Summary
    console.log('\nCleanup Summary:');
    console.log('----------------');
    let totalMatched = 0;
    let totalDeleted = 0;

    results.forEach(result => {
      console.log(`${result.collection}: ${result.itemsMatched} matched, ${result.itemsDeleted} deleted`);
      totalMatched += result.itemsMatched;
      totalDeleted += result.itemsDeleted;
    });

    console.log('----------------');
    console.log(`Total: ${totalMatched} matched, ${totalDeleted} deleted`);

    if (dryRun) {
      console.log('\nThis was a dry run. No records were actually deleted.');
      console.log('To perform the actual deletion, run without dryRun=true');
    }

    return {
      success: true,
      matched: totalMatched,
      deleted: totalDeleted,
      dryRun
    };
  } catch (error) {
    console.error('Error during database cleanup:', error);
    return {
      success: false,
      error: (error as Error).message
    };
  }
}

main()
  .then(result => {
    console.log('Cleanup finished!');
    process.exit(0);
  })
  .catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
  });

