// pages/api/admin/server-status.js
import { getServerSession } from "next-auth/next";
import { authOptions } from "../auth/[...nextauth]";
import { connectToDatabase } from "../../../lib/mongodb";
import { exec } from "child_process";
import { promisify } from "util";
import os from "os";

const execPromise = promisify(exec);

// Helper function to check if a service is running
async function checkServiceStatus(serviceName, checkCommand) {
  try {
    await execPromise(checkCommand);
    return {
      status: "healthy",
      message: `${serviceName} is running normally`
    };
  } catch (error) {
    console.error(`Error checking ${serviceName} status:`, error);
    return {
      status: "error",
      message: `Unable to connect to ${serviceName}: ${error.message}`
    };
  }
}

// Get MongoDB metrics
async function getMongoDBMetrics(db) {
  try {
    // Get server stats
    const serverStatus = await db.command({ serverStatus: 1 });

    // Get database stats
    const dbStats = await db.command({ dbStats: 1 });

    return {
      version: serverStatus.version,
      connections: serverStatus.connections.current,
      dbSize: dbStats.dataSize / (1024 * 1024), // Convert to MB
      uptime: serverStatus.uptime
    };
  } catch (error) {
    console.error("Error getting MongoDB metrics:", error);
    return {};
  }
}

// Get ChromaDB metrics
async function getChromaDBMetrics() {
  try {
    // This is a simplified example. In a real implementation, you would use
    // the ChromaDB client to get actual metrics.
    const response = await fetch("http://localhost:8000/api/v1/collections", {
      method: "GET",
      headers: {
        "Content-Type": "application/json"
      }
    });

    if (!response.ok) {
      throw new Error(`ChromaDB API error: ${response.status}`);
    }

    const data = await response.json();

    let totalEmbeddings = 0;

    // Sum up embeddings across collections
    if (Array.isArray(data)) {
      for (const collection of data) {
        // This assumes each collection has a count property
        totalEmbeddings += collection.count || 0;
      }
    }

    return {
      version: "latest", // You might want to get the actual version
      collections: Array.isArray(data) ? data.length : 0,
      totalEmbeddings
    };
  } catch (error) {
    console.error("Error getting ChromaDB metrics:", error);
    return {};
  }
}

// Get system metrics for the web server
function getSystemMetrics() {
  try {
    const uptime = process.uptime();

    // Memory usage
    const memUsage = process.memoryUsage();
    const memoryUsage = memUsage.rss / (1024 * 1024); // Convert to MB

    // CPU usage (simplified)
    const cpuUsage = os.loadavg()[0]; // 1-minute load average

    return {
      uptime,
      memoryUsage,
      cpuUsage
    };
  } catch (error) {
    console.error("Error getting system metrics:", error);
    return {};
  }
}

export default async function handler(req, res) {
  // Check authentication
  const session = await getServerSession(req, res, authOptions);

  if (!session || session.user.role !== "admin") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    // Connect to MongoDB
    const { db } = await connectToDatabase();

    // Check web server status (it's running if we got here)
    const webServerStatus = {
      status: "healthy",
      message: "Web server is running normally",
      metrics: getSystemMetrics()
    };

    // Check MongoDB status
    let mongodbStatus;
    try {
      await db.command({ ping: 1 });
      mongodbStatus = {
        status: "healthy",
        message: "MongoDB is connected and responding",
        metrics: await getMongoDBMetrics(db)
      };
    } catch (error) {
      mongodbStatus = {
        status: "error",
        message: `Unable to connect to MongoDB: ${error.message}`,
        metrics: {}
      };
    }

    // Check ChromaDB status
    let chromadbStatus;
    try {
      // Simple connection check
      const response = await fetch("http://localhost:8000/api/v1/heartbeat", {
        method: "GET"
      });

      if (response.ok) {
        chromadbStatus = {
          status: "healthy",
          message: "ChromaDB is connected and responding",
          metrics: await getChromaDBMetrics()
        };
      } else {
        throw new Error(`Status: ${response.status}`);
      }
    } catch (error) {
      chromadbStatus = {
        status: "error",
        message: `Unable to connect to ChromaDB: ${error.message}`,
        metrics: {}
      };
    }

    // Return all statuses
    return res.status(200).json({
      webServer: webServerStatus,
      mongodb: mongodbStatus,
      chromadb: chromadbStatus
    });
  } catch (error) {
    console.error("Error in server status API:", error);
    return res.status(500).json({ error: "Failed to fetch server status" });
  }
}

