import { useState, useEffect } from "react";
import AdminLayout from "../../components/layouts/AdminLayout";
import { useSession } from "next-auth/react";
import Head from "next/head";
import Link from "next/link";

export default function Dashboard() {
  const { data: session } = useSession();
  const [stats, setStats] = useState({
    serverHealth: "loading",
    totalCollections: 0,
    databaseSize: 0,
    scriptsAvailable: 0
  });

  useEffect(() => {
    const fetchStats = async () => {
      try {
        // In a real application, you would fetch these stats from an API
        const response = await fetch("/api/admin/dashboard-stats");

        if (response.ok) {
          const data = await response.json();
          setStats(data);
        }
      } catch (error) {
        console.error("Error fetching dashboard stats:", error);
      }
    };

    fetchStats();
  }, []);

  const StatusIndicator = ({ status }) => {
    const colors = {
      healthy: "bg-green-100 text-green-800",
      warning: "bg-yellow-100 text-yellow-800",
      error: "bg-red-100 text-red-800",
      loading: "bg-gray-100 text-gray-800"
    };

    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${colors[status] || colors.loading}`}>
        {status === "loading" ? "Loading..." : status.charAt(0).toUpperCase() + status.slice(1)}
      </span>
    );
  };

  return (
    <AdminLayout>
      <Head>
        <title>Admin Dashboard</title>
      </Head>

      <div className="py-6">
        <h1 className="text-2xl font-semibold text-gray-900">Dashboard</h1>
        <p className="mt-1 text-sm text-gray-500">
          Welcome back, {session?.user?.name || "Admin"}
