// pages/api/admin/available-scripts.js
import { getServerSession } from "next-auth/next";
import { authOptions } from "../auth/[...nextauth]";
import fs from "fs";
import path from "path";

export default async function handler(req, res) {
  // Check authentication
  const session = await getServerSession(req, res, authOptions);

  if (!session || session.user.role !== "admin") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    const scriptsDir = path.join(process.cwd(), "scripts");
    const testsDir = path.join(process.cwd(), "tests");

    // Get script files
    let scripts = [];
    if (fs.existsSync(scriptsDir)) {
      const scriptFiles = fs.readdirSync(scriptsDir);

      scripts = scriptFiles
        .filter(file => file.endsWith(".js") || file.endsWith(".ps1"))
        .map(file => {
          const filePath = path.join(scriptsDir, file);
          const fileStats = fs.statSync(filePath);
          const fileContent = fs.readFileSync(filePath, "utf8");

          // Simple metadata extraction (assuming metadata is in comments at the top)
          const descriptionMatch = fileContent.match(/\/\/ Description: (.+)/);
          const argsMatch = fileContent.match(/\/\/ Args: (.+)/);

          return {
            id: file,
            name: file.replace(/\.[^/.]+$/, ""), // Remove extension
            description: descriptionMatch ? descriptionMatch[1] : "No description available",
            arguments: argsMatch ? argsMatch[1].split(",").map(arg => arg.trim()) : [],
            type: file.endsWith(".js") ? "JavaScript" : "PowerShell",
            path: filePath,
            size: fileStats.size,
            lastModified: fileStats.mtime
          };
        });
    }

    // Get test files
    let tests = [];
    if (fs.existsSync(testsDir)) {
      const testFiles = fs.readdirSync(testsDir);

      tests = testFiles
        .filter(file => file.endsWith(".js") || file.endsWith(".ps1") || file.endsWith(".test.js"))
        .map(file => {
          const filePath = path.join(testsDir, file);
          const fileStats = fs.statSync(filePath);
          const fileContent = fs.readFileSync(filePath, "utf8");

          // Simple metadata extraction
          const descriptionMatch = fileContent.match(/\/\/ Description: (.+)/);

          return {
            id: file,
            name: file.replace(/\.[^/.]+$/, ""), // Remove extension
            description: descriptionMatch ? descriptionMatch[1] : "No description available",
            type: file.endsWith(".js") || file.endsWith(".test.js") ? "JavaScript" : "PowerShell",
            path: filePath,
            size: fileStats.size,
            lastModified: fileStats.mtime
          };
        });
    }

    return res.status(200).json({ scripts, tests });
  } catch (error) {
    console.error("Error in available-scripts API:", error);
    return res.status(500).json({ error: "Failed to fetch available scripts" });
  }
}

// pages/api/admin/run-script.js
import { getServerSession } from "next-auth/next";
import { authOptions } from "../auth/[...nextauth]";
import { exec } from "child_process";
import { promisify } from "util";
import path from "path";
import fs from "fs";

const execPromise = promisify(exec);

export default async function handler(req, res) {
  // Only allow POST requests
  if (req.method !== "POST") {
    return res.status(405).json({ error: "Method not allowed" });
  }

  // Check authentication
  const session = await getServerSession(req, res, authOptions);

  if (!session || session.user.role !== "admin") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  // Get script to run
  const { script } = req.body;

  if (!script) {
    return res.status(400).json({ error: "No script specified" });
  }

  try {
    // Determine if it's a script or a test
    const scriptsDir = path.join(process.cwd(), "scripts");
    const testsDir = path.join(process.cwd(), "tests");

    let scriptPath = path.join(scriptsDir, script);
    let scriptType = "script";

    if (!fs.existsSync(scriptPath)) {
      scriptPath = path.join(testsDir, script);
      scriptType = "test";

      if (!fs.existsSync(scriptPath)) {
        return res.status(404).json({ error: "Script not found" });
      }
    }

    // Validate script (additional security check)
    if (!script.endsWith(".js") && !script.endsWith(".ps1") && !script.endsWith(".test.js")) {
      return res.status(400).json({ error: "Invalid script type" });
    }

    // Execute the script
    let command;
    if (script.endsWith(".js") || script.endsWith(".test.js")) {
      command = `node "${scriptPath}"`;
    } else if (script.endsWith(".ps1")) {
      command = `powershell -ExecutionPolicy Bypass -File "${scriptPath}"`;
    }

    const { stdout, stderr } = await execPromise(command);

    if (stderr) {
      return res.status(500).json({ error: "Script execution failed", output: stderr });
    }

    return res.status(200).json({ output: stdout });
  } catch (error) {
    console.error("Error running script:", error);
    return res.status(500).json({ 
      error: "Failed to run script", 
      output: error.message 
    });
  }
}

// pages/api/admin/backup.js
import { getServerSession } from "next-auth/next";
import { authOptions } from "../auth/[...nextauth]";
import { exec } from "child_process";
import { promisify } from "util";
import path from "path";
import fs from "fs";

const execPromise = promisify(exec);

export default async function handler(req, res) {
  // Check authentication
  const session = await getServerSession(req, res, authOptions);

  if (!session || session.user.role !== "admin") {
    return res.status(401).json({ error: "Unauthorized" });
  }

  try {
    // Create backup directory if it doesn't exist
    const backupDir = path.join(process.cwd(), "backups");
    if (!fs.existsSync(backupDir)) {
      fs.mkdirSync(backupDir, { recursive: true });
    }

    // Generate timestamp for backup file
    const timestamp = new Date().toISOString().replace(/:/g, "-").replace(/\..+/, "");
    const backupFile = path.join(backupDir, `backup-${timestamp}.gz`);

    // Get MongoDB connection string from env
    const mongoUri = process.env.MONGODB_URI;
    const mongoDb = process.env.MONGODB_DB;

    if (!mongoUri || !mongoDb) {
      return res.status(500).json({ error: "MongoDB connection details not found in environment" });
    }

    // Execute mongodump command
    const command = `mongodump --uri="${mongoUri}" --db=${mongoDb} --gzip --archive="${backupFile}"`;
    await execPromise(command);

    return res.status(200).json({ 
      message: "Backup created successfully", 
      file: backupFile,
      timestamp: timestamp 
    });
  } catch (error) {
    console.error("Error creating backup:", error);
    return res.status(500).json({ error: "Failed to create backup" });
  }
}

// scripts/cleanup-database.js
// Description: Removes old and unused data from the database
// Args: days

import { MongoClient } from "mongodb";

async function main() {
  const days = process.argv[2] ? parseInt(process.argv[2]) : 30;
  console.log(`Cleaning up data older than ${days} days...`);

  // Calculate cutoff date
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - days);

  try {
    // Connect to MongoDB
    const client = await MongoClient.connect(process.env.MONGODB_URI);
    const db = client.db(process.env.MONGODB_DB);

    console.log("Connected to database");

    // Example: Remove old logs
    const logsResult = await db.collection("logs").deleteMany({
      createdAt: { $lt: cutoffDate }
    });

    console.log(`Removed ${logsResult.deletedCount} old log entries`);

    // Example: Clean up expired sessions
    const sessionsResult = await db.collection("sessions").deleteMany({
      expires: { $lt: new Date() }
    });

    console.log(`Removed ${sessionsResult.deletedCount} expired sessions`);

    // Close connection
    await client.close();
    console.log("Cleanup completed successfully");
  } catch (error) {
    console.error("Error during cleanup:", error);
    process.exit(1);
  }
}

main();

