# scripts/system-info.js
// Description: Provides information about the system and runtime
// Args: verbose

const os = require("os");

function formatBytes(bytes) {
  const units = ["B", "KB", "MB", "GB", "TB"];
  let i = 0;
  while (bytes >= 1024 && i < units.length - 1) {
    bytes /= 1024;
    i++;
  }
  return `${bytes.toFixed(2)} ${units[i]}`;
}

function formatUptime(seconds) {
  const days = Math.floor(seconds / (3600 * 24));
  const hours = Math.floor((seconds % (3600 * 24)) / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);

  return `${days}d ${hours}h ${minutes}m ${secs}s`;
}

function main() {
  const verbose = process.argv.includes("--verbose") || process.argv.includes("-v");

  console.log("=== System Information ===");
  console.log(`Hostname: ${os.hostname()}`);
  console.log(`Platform: ${os.platform()}`);
  console.log(`OS: ${os.type()} ${os.release()}`);
  console.log(`Architecture: ${os.arch()}`);
  console.log(`Uptime: ${formatUptime(os.uptime())}`);

  console.log("\n=== CPU Information ===");
  console.log(`CPUs: ${os.cpus().length} (${os.cpus()[0].model})`);
  console.log(`Load Average: ${os.loadavg().map(l => l.toFixed(2)).join(", ")}`);

  console.log("\n=== Memory Information ===");
  console.log(`Total Memory: ${formatBytes(os.totalmem())}`);
  console.log(`Free Memory: ${formatBytes(os.freemem())}`);
  console.log(`Memory Usage: ${((1 - os.freemem() / os.totalmem()) * 100).toFixed(2)}%`);

  if (verbose) {
    console.log("\n=== Network Interfaces ===");
    const interfaces = os.networkInterfaces();
    for (const [name, addresses] of Object.entries(interfaces)) {
      console.log(`Interface: ${name}`);
      addresses.forEach((addr, i) => {
        console.log(`  Address ${i+1}: ${addr.address} (${addr.family})`);
      });
    }

    console.log("\n=== Process Information ===");
    console.log(`Node Version: ${process.version}`);
    console.log(`Process ID: ${process.pid}`);
    console.log(`Current Directory: ${process.cwd()}`);

    console.log("\n=== Environment Variables ===");
    for (const [key, value] of Object.entries(process.env)) {
      // Filter out sensitive information
      if (!key.includes("KEY") && !key.includes("SECRET") && !key.includes("PASSWORD") && !key.includes("TOKEN")) {
        console.log(`${key}: ${value}`);
      }
    }
  }
}

main();

