// pages/api/health.js
import { connectToDatabase } from "../../lib/mongodb";

export default async function handler(req, res) {
  const environment = process.env.NODE_ENV || "development";
  const version = process.env.APP_VERSION || "1.0.0";

  try {
    // Check MongoDB connection
    let mongoStatus = "unknown";
    let chromaStatus = "unknown";

    try {
      const { db } = await connectToDatabase();
      await db.command({ ping: 1 });
      mongoStatus = "healthy";
    } catch (error) {
      console.error("MongoDB health check failed:", error);
      mongoStatus = "error";
    }

    // Check ChromaDB connection
    try {
      const response = await fetch("http://localhost:8000/api/v1/heartbeat", {
        method: "GET",
        timeout: 2000 // 2-second timeout
      });

      if (response.ok) {
        chromaStatus = "healthy";
      } else {
        chromaStatus = "error";
      }
    } catch (error) {
      console.error("ChromaDB health check failed:", error);
      chromaStatus = "error";
    }

    // Overall status
    const status = mongoStatus === "healthy" && chromaStatus === "healthy" 
      ? "healthy" 
      : mongoStatus === "error" || chromaStatus === "error" 
        ? "error" 
        : "warning";

    return res.status(200).json({
      status,
      environment,
      version,
      timestamp: new Date().toISOString(),
      services: {
        web: "healthy", // We're responding, so web server is up
        mongodb: mongoStatus,
        chromadb: chromaStatus
      }
    });
  } catch (error) {
    console.error("Health check error:", error);

    return res.status(500).json({
      status: "error",
      environment,
      version,
      timestamp: new Date().toISOString(),
      error: error.message
    });
  }
}

