import NextAuth, { NextAuthOptions } from "next-auth";
import CredentialsProvider from "next-auth/providers/credentials";
import { MongoDBAdapter } from "@next-auth/mongodb-adapter";
import { connectToDatabase } from "../../../lib/db/mongo"; // Adjust path to your existing mongo connection
import { compare } from "bcryptjs";
import { z } from "zod";

// Define user type
interface User {
  id: string;
  email: string;
  name: string;
  role: string;
}

// Validation schema for login credentials
const loginSchema = z.object({
  email: z.string().email("Invalid email address"),
  password: z.string().min(8, "Password must be at least 8 characters")
});

export const authOptions: NextAuthOptions = {
  adapter: MongoDBAdapter(connectToDatabase()),
  session: {
    strategy: "jwt",
    maxAge: 24 * 60 * 60 // 24 hours
  },
  providers: [
    CredentialsProvider({
      name: "Credentials",
      credentials: {
        email: { label: "Email", type: "email" },
        password: { label: "Password", type: "password" }
      },
      async authorize(credentials) {
        try {
          if (!credentials) {
            throw new Error("No credentials provided");
          }

          // Validate input
          const validInput = loginSchema.parse(credentials);

          // Connect to database
          const { db } = await connectToDatabase();

          // Find user
          const user = await db.collection("admins").findOne({ 
            email: validInput.email 
          });

          if (!user) {
            throw new Error("No user found with this email");
          }

          // Check password
          const isPasswordValid = await compare(
            validInput.password,
            user.password
          );

          if (!isPasswordValid) {
            throw new Error("Invalid password");
          }

          return {
            id: user._id.toString(),
            email: user.email,
            name: user.name,
            role: "admin"
          } as User;
        } catch (error) {
          console.error("Auth error:", error);
          return null;
        }
      }
    })
  ],
  callbacks: {
    async jwt({ token, user }) {
      if (user) {
        token.role = user.role;
      }
      return token;
    },
    async session({ session, token }) {
      if (session.user) {
        (session.user as any).role = token.role;
      }
      return session;
    }
  },
  pages: {
    signIn: "/admin/login",
    error: "/admin/error"
  },
  secret: process.env.NEXTAUTH_SECRET
};

export default NextAuth(authOptions);

// middleware.ts
import { NextRequest, NextResponse } from "next/server";
import { getToken } from "next-auth/jwt";

export async function middleware(req: NextRequest) {
  const token = await getToken({ 
    req, 
    secret: process.env.NEXTAUTH_SECRET 
  });

  const { pathname } = req.nextUrl;

  // Allow requests if:
  // 1. The token exists
  // 2. It's a request for next-auth session & provider
  // 3. It's the login page
  if (token || pathname.includes("/api/auth") || pathname === "/admin/login" || pathname === "/admin/error") {
    // If on login page and already logged in, redirect to dashboard
    if (pathname === "/admin/login" && token) {
      return NextResponse.redirect(new URL("/admin/dashboard", req.url));
    }

    return NextResponse.next();
  }

  // Otherwise, redirect to login page
  if (!token && pathname.startsWith("/admin")) {
    return NextResponse.redirect(new URL("/admin/login", req.url));
  }

  return NextResponse.next();
}

export const config = {
  matcher: ["/admin/:path*"]
};

