    async createUser(user) {
      const { db } = await connectToDatabase();
      const result = await db.collection("users").insertOne({
        ...user,
        emailVerified: user.emailVerified ? new Date(user.emailVerified) : null
      });

      const newUser = await db.collection("users").findOne({ _id: result.insertedId });
      return mongoUserToAdapterUser(newUser);
    },

    async getUser(id) {
      const { db } = await connectToDatabase();
      const user = await db.collection("users").findOne({ _id: new ObjectId(id) });
      if (!user) return null;
      return mongoUserToAdapterUser(user);
    },

    async getUserByEmail(email) {
      const { db } = await connectToDatabase();
      const user = await db.collection("users").findOne({ email });
      if (!user) return null;
      return mongoUserToAdapterUser(user);
    },

    async getUserByAccount({ provider, providerAccountId }) {
      const { db } = await connectToDatabase();
      const account = await db.collection("accounts").findOne({
        provider,
        providerAccountId
      });

      if (!account) return null;

      const user = await db.collection("users").findOne({ _id: new ObjectId(account.userId) });
      if (!user) return null;

      return mongoUserToAdapterUser(user);
    },

    async updateUser(user) {
      const { db } = await connectToDatabase();
      const { _id, ...userData } = user;

      await db.collection("users").updateOne(
        { _id: new ObjectId(_id) },
        { $set: userData }
      );

      const updatedUser = await db.collection("users").findOne({ _id: new ObjectId(_id) });
      return mongoUserToAdapterUser(updatedUser);
    },

    async deleteUser(userId) {
      const { db } = await connectToDatabase();
      const id = new ObjectId(userId);

      await Promise.all([
        db.collection("users").deleteOne({ _id: id }),
        db.collection("accounts").deleteMany({ userId: userId }),
        db.collection("sessions").deleteMany({ userId: userId }),
      ]);
    },

    async linkAccount(account) {
      const { db } = await connectToDatabase();

      const result = await db.collection("accounts").insertOne({
        ...account,
        userId: account.userId.toString(),
      });

      const newAccount = await db.collection("accounts").findOne({ _id: result.insertedId });
      return newAccount;
    },

    async unlinkAccount({ provider, providerAccountId }) {
      const { db } = await connectToDatabase();

      await db.collection("accounts").deleteOne({
        provider,
        providerAccountId,
      });
    },

    async createSession(session) {
      const { db } = await connectToDatabase();

      const result = await db.collection("sessions").insertOne({
        ...session,
        userId: session.userId.toString(),
        expires: new Date(session.expires),
      });

      const newSession = await db.collection("sessions").findOne({ _id: result.insertedId });
      return mongoSessionToAdapterSession(newSession);
    },

    async getSessionAndUser(sessionToken) {
      const { db } = await connectToDatabase();

      const session = await db.collection("sessions").findOne({ sessionToken });
      if (!session) return null;

      const user = await db.collection("users").findOne({ _id: new ObjectId(session.userId) });
      if (!user) return null;

      return {
        session: mongoSessionToAdapterSession(session),
        user: mongoUserToAdapterUser(user),
      };
    },

    async updateSession(session) {
      const { db } = await connectToDatabase();

      await db.collection("sessions").updateOne(
        { sessionToken: session.sessionToken },
        { $set: { expires: new Date(session.expires) } }
      );

      const updatedSession = await db.collection("sessions").findOne({ sessionToken: session.sessionToken });
      if (!updatedSession) return null;

      return mongoSessionToAdapterSession(updatedSession);
    },

    async deleteSession(sessionToken) {
      const { db } = await connectToDatabase();

      await db.collection("sessions").deleteOne({ sessionToken });
    },

    async createVerificationToken(verificationToken) {
      const { db } = await connectToDatabase();

      const { identifier, expires, token } = verificationToken;
      await db.collection("verification_tokens").insertOne({
        identifier,
        token,
        expires: new Date(expires),
      });

      return verificationToken;
    },

    async useVerificationToken({ identifier, token }) {
      const { db } = await connectToDatabase();

      const verificationToken = await db.collection("verification_tokens").findOne({
        identifier,
        token,
      });

      if (!verificationToken) return null;

      await db.collection("verification_tokens").deleteOne({
        identifier,
        token,
      });

      return {
        identifier: verificationToken.identifier,
        token: verificationToken.token,
        expires: verificationToken.expires.toISOString(),
      };
    },
  };
}

// Helper functions to convert MongoDB objects to NextAuth format
function mongoUserToAdapterUser(user: any): AdapterUser {
  if (!user) return null;
  return {
    ...user,
    id: user._id.toString(),
    emailVerified: user.emailVerified instanceof Date
      ? user.emailVerified.toISOString()
      : user.emailVerified,
  };
}

function mongoSessionToAdapterSession(session: any): AdapterSession {
  if (!session) return null;
  return {
    ...session,
    id: session._id.toString(),
    expires: session.expires.toISOString(),
  };
}

