  email: string;
  name: string;
  image?: string;
  role: UserRole;
  passwordHash: string;
  createdAt: Date;
  updatedAt: Date;
}

export type UserCreateInput = Omit<User, '_id' | 'createdAt' | 'updatedAt'>;
export type UserUpdateInput = Partial<
  Omit<User, '_id' | 'createdAt' | 'updatedAt'>
>;

// Create a type that represents the user data stored in the JWT token and session
// Typically you don't want to expose passwordHash in the token/session
export type AuthUser = {
  id: string;
  email: string;
  name: string;
  image?: string;
  role: UserRole;
};

// types/next-auth.d.ts
import { UserRole } from './user';
import { DefaultSession, DefaultUser } from "next-auth";
import { JWT } from "next-auth/jwt";

// Extend the built-in NextAuth types
declare module "next-auth" {
  /**
   * Returned by useSession, getSession and received as a prop by SessionProvider
   */
  interface Session {
    user: {
      id: string;
      role: UserRole;
    } & DefaultSession["user"];
  }

  /**
   * The shape of the user object returned in the OAuth providers' callback
   */
  interface User extends DefaultUser {
    role: UserRole;
  }
}

/**
 * The shape of the JWT token stored in the session
 */
declare module "next-auth/jwt" {
  interface JWT {
    id?: string;
    role?: UserRole;
  }
}

