// scripts/cleanup-database.ts
// Description: Removes old and unused data from the database
// Args: days

import { MongoClient, Db } from "mongodb";
import { config } from "dotenv";

// Load environment variables from .env.local
config({ path: ".env.local" });

interface CleanupResult {
  collection: string;
  deletedCount: number;
}

interface CleanupSummary {
  totalDeleted: number;
  collections: CleanupResult[];
}

/**
 * Cleans up old data from the specified collections
 * @param db The MongoDB database instance
 * @param cutoffDate The date before which records should be deleted
 * @param collections Array of collection names to clean up
 * @returns A summary of cleanup results
 */
async function cleanupCollections(
  db: Db, 
  cutoffDate: Date, 
  collections: string[]
): Promise<CleanupSummary> {
  const results: CleanupResult[] = [];
  let totalDeleted = 0;

  for (const collection of collections) {
    try {
      // Check if collection exists
      const collectionExists = await db.listCollections({ name: collection }).hasNext();

      if (collectionExists) {
        // Delete old records
        const result = await db.collection(collection).deleteMany({
          createdAt: { $lt: cutoffDate }
        });

        results.push({
          collection,
          deletedCount: result.deletedCount || 0
        });

        totalDeleted += result.deletedCount || 0;

        console.log(`Cleaned up ${result.deletedCount} documents from ${collection}`);
      } else {
        console.log(`Collection ${collection} does not exist, skipping...`);
      }
    } catch (error) {
      console.error(`Error cleaning up collection ${collection}:`, error);
      results.push({
        collection,
        deletedCount: 0
      });
    }
  }

  return {
    totalDeleted,
    collections: results
  };
}

/**
 * Cleans up expired sessions
 * @param db The MongoDB database instance
 * @returns Number of deleted sessions
 */
async function cleanupExpiredSessions(db: Db): Promise<number> {
  try {
    // Check if sessions collection exists
    const collectionExists = await db.listCollections({ name: "sessions" }).hasNext();

    if (collectionExists) {
      const result = await db.collection("sessions").deleteMany({
        expires: { $lt: new Date() }
      });

      console.log(`Removed ${result.deletedCount} expired sessions`);
      return result.deletedCount || 0;
    } else {
      console.log("Sessions collection does not exist, skipping...");
      return 0;
    }
  } catch (error) {
    console.error("Error cleaning up sessions:", error);
    return 0;
  }
}

async function main(): Promise<void> {
  // Get days argument from command line or use default (30 days)
  const args = process.argv.slice(2);
  const days = args.length > 0 ? parseInt(args[0]) : 30;

  if (isNaN(days) || days <= 0) {
    console.error("Invalid days parameter. Must be a positive number.");
    process.exit(1);
  }

  console.log(`Cleaning up data older than ${days} days...`);

  // Calculate cutoff date
  const cutoffDate = new Date();
  cutoffDate.setDate(cutoffDate.getDate() - days);

  // Get MongoDB URI from environment variables
  const mongoUri = process.env.MONGODB_URI;
  const dbName = process.env.MONGODB_DB;

  if (!mongoUri || !dbName) {
    console.error("MongoDB connection details not found in environment variables");
    process.exit(1);
  }

  let client: MongoClient | null = null;

  try {
    // Connect to MongoDB
    client = await MongoClient.connect(mongoUri);
    const db = client.db(dbName);

    console.log("Connected to database");

    // Collections to clean up (add more as needed)
    const collectionsToCleanup = [
      "logs",
      "activity",
      "notifications",
      "temporary_data"
    ];

    // Perform cleanup operations
    const cleanupResults = await cleanupCollections(db, cutoffDate, collectionsToCleanup);
    const sessionsDeleted = await cleanupExpiredSessions(db);

    // Print summary
    console.log("\nCleanup Summary:");
    console.log("=====================================");
    console.log(`Total documents deleted: ${cleanupResults.totalDeleted + sessionsDeleted}`);
    console.log("- By collection:");

    cleanupResults.collections.forEach(result => {
      console.log(`  • ${result.collection}: ${result.deletedCount} documents`);
    });

    console.log(`  • sessions: ${sessionsDeleted} documents`);
    console.log("=====================================");

    console.log("Cleanup completed successfully");
  } catch (error) {
    console.error("Error during cleanup:", error);
    process.exit(1);
  } finally {
    // Close MongoDB connection
    if (client) {
      await client.close();
      console.log("Database connection closed");
    }
  }
}

// Run the main function
main().catch(error => {
  console.error("Fatal error:", error);
  process.exit(1);
});

// pages/api/health.ts
import { NextApiRequest, NextApiResponse } from 'next';
import { connectToDatabase } from "../../lib/db/mongo";

// Define types for health check response
type HealthStatus = 'healthy' | 'warning' | 'error';

interface ServiceHealth {
  status: HealthStatus;
  details?: Record<string, any>;
}

interface HealthCheckResponse {
  status: HealthStatus;
  environment: string;
  version: string;
  timestamp: string;
  services: {
    web: ServiceHealth;
    mongodb: ServiceHealth;
    chromadb: ServiceHealth;
  };
}

interface ErrorResponse {
  status: 'error';
  environment: string;
  version: string;
  timestamp: string;
  error: string;
}

/**
 * Check MongoDB connection health
 * @returns Promise resolving to MongoDB health status
 */
async function checkMongoDBHealth(): Promise<ServiceHealth> {
  try {
    const { db } = await connectToDatabase();

    // Ping MongoDB to verify connection
    await db.command({ ping: 1 });

    // Get some basic stats
    const serverStatus = await db.command({ serverStatus: 1 });

    return {
      status: 'healthy',
      details: {
        version: serverStatus.version,
        uptime: serverStatus.uptime,
        connections: serverStatus.connections.current
      }
    };
  } catch (error) {
    console.error("MongoDB health check failed:", error);
    return {
      status: 'error',
      details: {
        message: (error as Error).message
      }
    };
  }
}

/**
 * Check ChromaDB connection health
 * @returns Promise resolving to ChromaDB health status
 */
async function checkChromaDBHealth(): Promise<ServiceHealth> {
  try {
    // Try to connect to ChromaDB heartbeat endpoint
    const response = await fetch("http://localhost:8000/api/v1/heartbeat", {
      method: "GET",
      headers: {
        "Content-Type": "application/json"
      },
      signal: AbortSignal.timeout(2000) // 2-second timeout
    });

    if (!response.ok) {
      throw new Error(`ChromaDB returned status: ${response.status}`);
    }

    // Get collections to add detail
    const collectionsResponse = await fetch("http://localhost:8000/api/v1/collections", {
      method: "GET",
      headers: {
        "Content-Type": "application/json"
      }
    });

    let collections: any[] = [];
    if (collectionsResponse.ok) {
      collections = await collectionsResponse.json();
    }

    return {
      status: 'healthy',
      details: {
        collectionCount: Array.isArray(collections) ? collections.length : 0
      }
    };
  } catch (error) {
    console.error("ChromaDB health check failed:", error);
    return {
      status: 'error',
      details: {
        message: (error as Error).message
      }
    };
  }
}

/**
 * Health check API endpoint
 */
export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse<HealthCheckResponse | ErrorResponse>
): Promise<void> {
  const environment = process.env.NODE_ENV || "development";
  const version = process.env.APP_VERSION || "1.0.0";
  const timestamp = new Date().toISOString();

  try {
    // Run health checks in parallel for efficiency
    const [mongodbHealth, chromadbHealth] = await Promise.all([
      checkMongoDBHealth(),
      checkChromaDBHealth()
    ]);

    // Web server is healthy if we're responding
    const webHealth: ServiceHealth = {
      status: 'healthy',
      details: {
        uptime: process.uptime()
      }
    };

    // Determine overall system health based on service health
    let overallStatus: HealthStatus = 'healthy';

    if (mongodbHealth.status === 'error' || chromadbHealth.status === 'error') {
      overallStatus = 'error';
    } else if (mongodbHealth.status === 'warning' || chromadbHealth.status === 'warning') {
      overallStatus = 'warning';
    }

    const healthResponse: HealthCheckResponse = {
      status: overallStatus,
      environment,
      version,
      timestamp,
      services: {
        web: webHealth,
        mongodb: mongodbHealth,
        chromadb: chromadbHealth
      }
    };

    // Set appropriate cache headers to prevent caching
    res.setHeader('Cache-Control', 'no-store, max-age=0');

    return res.status(200).json(healthResponse);
  } catch (error) {
    console.error("Health check error:", error);

    const errorResponse: ErrorResponse = {
      status: 'error',
      environment,
      version,
      timestamp,
      error: (error as Error).message
    };

    return res.status(500).json(errorResponse);
  }
}

