'use client';
import { useState, useEffect, FormEvent } from 'react';
import AdminLayout from '../../../components/layout/AdminLayout';
import { useSession } from 'next-auth/react';
import Head from 'next/head';

// Define types for scripts and tests
interface ScriptItem {
  id: string;
  name: string;
  description: string;
  type: string;
  path: string;
  arguments?: string[];
  size: number;
  lastModified: string;
}

interface ScriptsResponse {
  scripts: ScriptItem[];
  tests: ScriptItem[];
}

interface ScriptRunResponse {
  output: string;
}

export default function ScriptsPage() {
  const { data: session } = useSession();
  const [scripts, setScripts] = useState<ScriptItem[]>([]);
  const [tests, setTests] = useState<ScriptItem[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedScript, setSelectedScript] = useState<ScriptItem | null>(null);
  const [scriptOutput, setScriptOutput] = useState<string>('');
  const [isRunning, setIsRunning] = useState<boolean>(false);

  useEffect(() => {
    const fetchScripts = async () => {
      try {
        const response = await fetch('/api/admin/available-scripts');

        if (!response.ok) {
          throw new Error(`Error: ${response.status}`);
        }

        const data: ScriptsResponse = await response.json();
        setScripts(data.scripts || []);
        setTests(data.tests || []);
      } catch (err) {
        setError((err as Error).message);
        console.error('Failed to fetch scripts:', err);
      } finally {
        setIsLoading(false);
      }
    };

    if (session) {
      fetchScripts();
    }
  }, [session]);

  const handleScriptSelect = (script: ScriptItem) => {
    setSelectedScript(script);
    setScriptOutput('');
  };

  const handleRunScript = async () => {
    if (!selectedScript) return;

    setIsRunning(true);
    setScriptOutput('Running script...');

    try {
      const response = await fetch('/api/admin/run-script', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ script: selectedScript.id }),
      });

      if (!response.ok) {
        throw new Error(`Error: ${response.status}`);
      }

      const data: ScriptRunResponse = await response.json();
      setScriptOutput(data.output || 'Script completed successfully.');
    } catch (err) {
      setScriptOutput(`Error: ${(err as Error).message}`);
      console.error('Failed to run script:', err);
    } finally {
      setIsRunning(false);
    }
  };

  return (
    <AdminLayout>
      <Head>
        <title>Scripts & Tests | Admin Dashboard</title>
      </Head>

      <div className="py-6">
        <h1 className="text-2xl font-semibold text-gray-900">
          Scripts & Tests
        </h1>
        <p className="mt-1 text-sm text-gray-500">
          Run maintenance scripts and tests
        </p>
      </div>

      {isLoading ? (
        <div className="mt-8 flex justify-center">
          <svg
            className="h-8 w-8 animate-spin text-blue-600"
            xmlns="http://www.w3.org/2000/svg"
            fill="none"
            viewBox="0 0 24 24"
          >
            <circle
              className="opacity-25"
              cx="12"
              cy="12"
              r="10"
              stroke="currentColor"
              strokeWidth="4"
            ></circle>
            <path
              className="opacity-75"
              fill="currentColor"
              d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
            ></path>
          </svg>
        </div>
      ) : error ? (
        <div className="mt-4 border-l-4 border-red-400 bg-red-50 p-4">
          <div className="flex">
            <div className="flex-shrink-0">
              <svg
                className="h-5 w-5 text-red-400"
                xmlns="http://www.w3.org/2000/svg"
                viewBox="0 0 20 20"
                fill="currentColor"
              >
                <path
                  fillRule="evenodd"
                  d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"
                  clipRule="evenodd"
                />
              </svg>
            </div>
            <div className="ml-3">
              <p className="text-sm text-red-700">{error}</p>
            </div>
          </div>
        </div>
      ) : (
        <div className="mt-4 grid grid-cols-1 gap-6 lg:grid-cols-3">
          {/* Script List */}
          <div className="lg:col-span-1">
