                  clipRule="evenodd"
                />
              </svg>
            </div>
            <div className="ml-3">
              <p className="text-sm text-red-700">{error}</p>
            </div>
          </div>
        </div>
      ) : (
        <div className="mt-4">
          {lastUpdated && (
            <p className="mb-4 text-xs text-gray-500">
              Last updated: {lastUpdated.toLocaleString()}
            </p>
          )}

          <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
